let avifFile = null;
let avifImage = null;
let outputFormat = 'jpg';

const avifDropzone = document.getElementById('dropzone');
const avifFileInput = document.getElementById('fileInput');
const avifBrowseBtn = document.getElementById('browseBtn');
const avifWorkspace = document.getElementById('workspace');
const avifResultArea = document.getElementById('resultArea');
const avifFormatSel = document.getElementById('formatSel');
const avifConvertBtn = document.getElementById('convertBtn');
const avifResetBtn = document.getElementById('resetBtn');
const avifDownloadBtn = document.getElementById('downloadBtn');
const avifPreview = document.getElementById('preview');

avifDropzone.addEventListener('dragover', e => { e.preventDefault(); avifDropzone.classList.add('drag'); });
avifDropzone.addEventListener('dragleave', () => { avifDropzone.classList.remove('drag'); });
avifDropzone.addEventListener('drop', e => {
  e.preventDefault();
  avifDropzone.classList.remove('drag');
  if (e.dataTransfer.files.length) handleAvifFile(e.dataTransfer.files[0]);
});
avifFileInput.addEventListener('change', e => { if (e.target.files[0]) handleAvifFile(e.target.files[0]); });
avifBrowseBtn && avifBrowseBtn.addEventListener('click', () => avifFileInput.click());

function handleAvifFile(file) {
  if (!file || !file.name.toLowerCase().endsWith('.avif')) {
    alert('Please select an AVIF file.');
    return;
  }
  avifFile = file;
  const url = URL.createObjectURL(file);
  avifImage = new Image();
  avifImage.onload = () => {
    avifPreview.src = url;
    avifDropzone.style.display = 'none';
    avifWorkspace.style.display = 'block';
  };
  avifImage.onerror = () => { alert('Failed to load AVIF image.'); };
  avifImage.src = url;
}

async function convertAvif() {
  if (!avifFile) return;
  avifConvertBtn.disabled = true;
  avifResultArea.textContent = 'Converting...';
  try {
    const blob = await heic2any({ blob: avifFile, toType: 'image/' + outputFormat });
    const out = Array.isArray(blob) ? blob[0] : blob;
    const url = URL.createObjectURL(out);
    avifResultArea.innerHTML = '<a href="' + url + '" download="converted.' + outputFormat + '">Unduh</a>';
  } catch (err) {
    avifResultArea.textContent = 'Error: ' + err.message;
  } finally {
    avifConvertBtn.disabled = false;
  }
}

avifConvertBtn && avifConvertBtn.addEventListener('click', convertAvif);
avifResetBtn && avifResetBtn.addEventListener('click', () => {
  avifFile = null;
  avifImage = null;
  avifWorkspace.style.display = 'none';
  avifDropzone.style.display = '';
  avifResultArea.textContent = '';
  avifFileInput.value = '';
});

let files = [];
let model = null;
let processing = false;

const fileInput = document.getElementById('fileInput');
const dropzone = document.getElementById('dropzone');
const workspace = document.getElementById('workspace');
const previewList = document.getElementById('previewList');
const removeBtn = document.getElementById('removeBtn');
const downloadAllBtn = document.getElementById('downloadAllBtn');
const addMoreBtn = document.getElementById('addMoreBtn');
const clearBtn = document.getElementById('clearBtn');
const progBar = document.getElementById('progBar');
const progFill = document.getElementById('progFill');
const status = document.getElementById('status');
const beforeAfter = document.getElementById('beforeAfterPreview');

fileInput.addEventListener('change', () => {
  const arr = Array.from(fileInput.files).filter(f => f.type && f.type.startsWith('image/'));
  if (arr.length) addFiles(arr);
  fileInput.value = '';
});
dropzone.addEventListener('dragover', e => { e.preventDefault(); dropzone.classList.add('drag'); });
dropzone.addEventListener('dragleave', () => { dropzone.classList.remove('drag'); });
dropzone.addEventListener('drop', e => {
  e.preventDefault();
  dropzone.classList.remove('drag');
  const arr = Array.from(e.dataTransfer.files).filter(f => f.type && f.type.startsWith('image/'));
  if (arr.length) addFiles(arr);
});

function addFiles(arr) {
  files = files.concat(arr.map(f => ({ name: f.name, file: f, url: URL.createObjectURL(f), resultUrl: null, resultBlob: null })));
  dropzone.style.display = 'none';
  workspace.style.display = 'block';
  if (beforeAfter) beforeAfter.classList.add('hidden');
  renderList();
}

function formatSize(bytes) {
  if (bytes < 1024) return bytes + ' B';
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
  return (bytes / (1024 * 1024)).toFixed(2) + ' MB';
}

function renderList() {
  previewList.innerHTML = '';
  files.forEach((item, i) => {
    const div = document.createElement('div');
    div.className = 'prev-item';
    const outName = item.name.replace(/\.[^.]+$/, '') + '-no-bg.png';
    let info = '<p>Original: ' + formatSize(item.file.size) + '</p>';
    let dl = '';
    if (item.resultBlob) {
      info += '<p><span class="badge badge-done">✅ Done</span> Output: ' + formatSize(item.resultBlob.size) + '</p>';
      dl = '<a href="' + item.resultUrl + '" download="' + outName + '" class="btn btn-secondary" style="padding:4px 10px;font-size:0.8rem;align-self:center">Download</a>';
    } else if (processing) {
      info += '<p><span class="badge badge-processing">⏳ Processing...</span></p>';
    } else {
      info += '<p>⏳ Waiting...</p>';
    }
    div.innerHTML = '<img class="thumb" src="' + item.url + '"><div class="info"><p><strong>' + item.name + '</strong></p>' + info + '</div>' + dl + '<button title="Remove" style="align-self:flex-start">✕</button>';
    div.querySelector('button').addEventListener('click', function(e) {
      e.stopPropagation();
      URL.revokeObjectURL(item.url);
      if (item.resultUrl) URL.revokeObjectURL(item.resultUrl);
      files.splice(i, 1);
      renderList();
    });
    previewList.appendChild(div);
  });
  const done = files.filter(function(f) { return f.resultBlob; });
  downloadAllBtn.style.display = done.length > 1 ? 'inline-block' : 'none';
}

addMoreBtn.addEventListener('click', function() { fileInput.click(); });

removeBtn.addEventListener('click', async function() {
  if (!files.length || processing) return;
  processing = true;
  removeBtn.disabled = true;
  progBar.style.display = 'block';
  renderList();

  // Load model once
  if (!model) {
    status.textContent = 'Loading AI model (first time may take a moment)...';
    try {
      const mod = await import('https://cdn.jsdelivr.net/npm/@imgly/background-removal@1.7.0/+esm');
      model = mod;
    } catch (err) {
      status.textContent = 'Failed to load model: ' + err.message;
      processing = false;
      removeBtn.disabled = false;
      return;
    }
  }

  for (let i = 0; i < files.length; i++) {
    if (files[i].resultBlob) { progFill.style.width = (((i + 1) / files.length) * 100) + '%'; continue; }
    status.textContent = 'Removing background ' + (i+1) + '/' + files.length + ': ' + files[i].name;
    progFill.style.width = ((i / files.length) * 100) + '%';
    renderList();
    try {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      const imgUrl = files[i].url;
      await new Promise(function(resolve, reject) {
        img.onload = resolve;
        img.onerror = reject;
        img.src = imgUrl;
      });
      const blob = await model.removeBackground(imgUrl);
      files[i].resultBlob = blob;
      files[i].resultUrl = URL.createObjectURL(blob);
    } catch (err) {
      status.textContent = 'Error on ' + files[i].name + ': ' + (err && err.message ? err.message : err);
      console.error(err);
    }
  }
  progFill.style.width = '100%';
  processing = false;
  removeBtn.disabled = false;
  const doneCount = files.filter(function(f) { return f.resultBlob; }).length;
  status.textContent = 'Done! ' + doneCount + ' / ' + files.length + ' processed.';
  setTimeout(function() { progBar.style.display = 'none'; status.textContent = ''; }, 4000);
  renderList();
});

downloadAllBtn.addEventListener('click', async function() {
  const zip = new JSZip();
  files.forEach(function(item) {
    if (item.resultBlob) {
      const outName = item.name.replace(/\.[^.]+$/, '') + '-no-bg.png';
      zip.file(outName, item.resultBlob);
    }
  });
  status.textContent = 'Creating ZIP...';
  const blob = await zip.generateAsync({ type: 'blob' });
  const a = document.createElement('a');
  a.download = 'no-background-images.zip';
  a.href = URL.createObjectURL(blob);
  a.click();
  URL.revokeObjectURL(a.href);
  status.textContent = 'ZIP downloaded!';
  setTimeout(function() { status.textContent = ''; }, 2000);
});

clearBtn.addEventListener('click', function() {
  files.forEach(function(f) { URL.revokeObjectURL(f.url); if (f.resultUrl) URL.revokeObjectURL(f.resultUrl); });
  files = [];
  previewList.innerHTML = '';
  workspace.style.display = 'none';
  dropzone.style.display = '';
  progBar.style.display = 'none';
  status.textContent = '';
  if (beforeAfter) beforeAfter.classList.remove('hidden');
});

// Sample image
(function() {
  var sampleBtn = document.getElementById('sampleBtn');
  if (sampleBtn) {
    sampleBtn.addEventListener('click', async function(e) {
      e.stopPropagation(); e.preventDefault();
      sampleBtn.textContent = '⏳ Loading...';
      try {
        const resp = await fetch('https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=800&q=80');
        const blob = await resp.blob();
        const file = new File([blob], 'sample.jpg', { type: 'image/jpeg' });
        addFiles([file]);
        sampleBtn.textContent = '🖼️ Try with a sample image';
      } catch (err) { sampleBtn.textContent = '🖼️ Try with a sample image'; }
    });
  }
})();
