  })();

tools.inline_style:
.tool-container{max-width:960px;margin:2rem auto;padding:0 1rem}
.controls{display:flex;flex-wrap:wrap;gap:0.75rem;align-items:center;justify-content:flex-start;margin:0.5rem 0}
.controls label{font-weight:600;font-size:0.85rem;color:var(--text-secondary);white-space:nowrap}
.controls select,.controls input[type=number],.controls input[type=text]{padding:7px 10px;border:1px solid var(--border-color);border-radius:var(--radius-sm);font-size:0.9rem;background:var(--bg-secondary);color:var(--text-primary);outline:none;transition:var(--transition)}
.controls select:focus,.controls input:focus{border-color:var(--accent);box-shadow:0 0 0 2px var(--accent-glow)}
.controls select{min-width:120px}
.controls input[type=number]{width:72px}
.controls input[type=text]{width:150px}
.controls input[type=range]{accent-color:var(--accent);background:var(--bg-tertiary);border-radius:4px;height:6px}
.controls input[type=range]::-webkit-slider-thumb{appearance:none;width:16px;height:16px;border-radius:50%;background:var(--accent);cursor:pointer}
.controls input[type=checkbox]{accent-color:var(--accent);width:16px;height:16px;cursor:pointer}
.range-value{font-size:0.85rem;color:var(--text-secondary);min-width:35px;text-align:center}
.btn{padding:10px 24px;border:none;border-radius:var(--radius-md);font-size:0.9rem;cursor:pointer;font-weight:600;transition:var(--transition);display:inline-flex;align-items:center;gap:6px}
.btn-primary{background:var(--accent);color:#fff}
.btn-primary:hover{background:var(--accent-light);box-shadow:0 0 20px var(--accent-glow)}
.btn-secondary{background:var(--bg-tertiary);color:var(--text-primary);border:1px solid var(--border-color)}
.btn-secondary:hover{background:var(--bg-card-hover);border-color:var(--accent)}
.btn-success{background:var(--success);color:#fff}
.btn-success:hover{background:#16a34a}
.btn-sm{padding:6px 14px;font-size:0.82rem}
.btn:disabled{opacity:0.5;cursor:not-allowed;pointer-events:none}
.upload-area{border:2px dashed var(--border-color);border-radius:var(--radius-lg);padding:3rem 2rem;text-align:center;cursor:pointer;transition:var(--transition);background:var(--bg-card)}
.upload-area:hover,.upload-area.dragover{border-color:var(--accent);background:var(--bg-card-hover);box-shadow:0 0 30px var(--accent-glow)}
.upload-icon{font-size:3rem;margin-bottom:0.5rem}
.upload-area h3{font-size:1.2rem;margin:0.5rem 0}
.upload-area p{color:var(--text-secondary);font-size:0.9rem;margin:0.25rem 0}
.upload-hint{font-size:0.8rem;color:var(--text-muted)}
.file-list{display:flex;flex-direction:column;gap:0.4rem;margin:1rem 0;max-height:360px;overflow-y:auto;padding-right:4px}
.file-list::-webkit-scrollbar{width:4px}
.file-list::-webkit-scrollbar-thumb{background:var(--border-color);border-radius:2px}
.file-item{display:flex;align-items:center;gap:0.75rem;padding:0.5rem 0.75rem;background:var(--bg-card);border:1px solid var(--border-color);border-radius:var(--radius-sm);font-size:0.85rem;transition:var(--transition)}
.file-item:hover{background:var(--bg-card-hover)}
.file-item .fnum{color:var(--text-muted);font-size:0.75rem;min-width:24px}
.file-item .fname{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
