.file-item .file-compare.nosave{color:var(--text-muted)}
details.options-panel{background:var(--bg-card);border:1px solid var(--border-color);border-radius:var(--radius-md);padding:0.75rem 1rem;margin:1rem 0}
details.options-panel summary{cursor:pointer;font-weight:600;font-size:0.92rem;color:var(--text-primary);padding:0.25rem 0}
details.options-panel summary:hover{color:var(--accent)}
