.preset-btn{padding:8px 12px;border:1px solid var(--border-color);border-radius:var(--radius-sm);background:var(--bg-tertiary);cursor:pointer;text-align:left;font-size:0.82rem;color:var(--text-primary);transition:var(--transition);line-height:1.4}
