.preset-btn.active{border-color:var(--accent);background:rgba(99,102,241,0.1);box-shadow:0 0 10px var(--accent-glow)}
.preset-btn strong{display:block;font-size:0.88rem}
.preset-btn span{font-size:0.75rem;color:var(--text-muted)}
.progress-bar{width:100%;height:10px;background:var(--bg-tertiary);border-radius:5px;overflow:hidden;margin:0.75rem 0}
.progress-fill{height:100%;background:linear-gradient(90deg,var(--gradient-from),var(--gradient-to));transition:width 0.25s;border-radius:5px}
.status{text-align:center;padding:0.4rem;font-size:0.88rem;color:var(--text-secondary)}
.file-progress{width:50px;height:4px;background:var(--bg-tertiary);border-radius:2px;overflow:hidden;flex-shrink:0}
.file-progress-fill{height:100%;background:var(--accent);transition:width 0.2s;border-radius:2px;width:0%}
.stats-bar{display:flex;flex-wrap:wrap;gap:1rem;padding:0.75rem 0;margin:0.5rem 0;border-top:1px solid var(--border-color);border-bottom:1px solid var(--border-color)}
.stat-item{font-size:0.82rem;color:var(--text-secondary)}
.stat-item strong{color:var(--text-primary);margin-right:3px}
.summary-table{width:100%;border-collapse:collapse;font-size:0.82rem;margin:0.5rem 0}
.summary-table th{text-align:left;padding:6px 8px;color:var(--text-muted);font-weight:500;border-bottom:1px solid var(--border-color)}
.summary-table td{padding:6px 8px;border-bottom:1px solid var(--border-color);color:var(--text-secondary)}
.summary-table td:last-child{text-align:right}
.summary-table .saved-row{background:rgba(34,197,94,0.05)}
.toast{position:fixed;bottom:30px;right:30px;background:var(--bg-card);border:1px solid var(--border-color);border-radius:var(--radius-md);padding:12px 20px;font-size:0.85rem;color:var(--text-primary);box-shadow:var(--shadow-lg);z-index:1000;opacity:0;transform:translateY(20px);transition:var(--transition);pointer-events:none}
.toast.show{opacity:1;transform:translateY(0);pointer-events:auto}
@media(max-width:640px){
  .controls{gap:0.5rem}
  .controls input[type=number]{width:60px}
  .controls input[type=text]{width:120px}
  .preset-grid{grid-template-columns:1fr 1fr}
  .stats-bar{flex-direction:column;gap:0.4rem}
}

