  const $ = id => document.getElementById(id);
  const fileInput = $('fileInput'), uploadArea = $('uploadArea'), workspace = $('workspace');
  const fileList = $('fileList'), processBtn = $('processBtn'), downloadBtn = $('downloadBtn');
  const quality = $('quality'), progBar = $('progBar'), progFill = $('progFill'), statusText = $('statusText');
  const enableRename = $('enableRename'), renamePrefix = $('renamePrefix'), renameStart = $('renameStart');

