  }

  function formatSize(bytes) {
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1048576) return (bytes / 1024).toFixed(1) + ' KB';
    return (bytes / 1048576).toFixed(1) + ' MB';
  }

  function renderList() {
    fileList.innerHTML = '';
    files.forEach((f, i) => {
      const div = document.createElement('div');
      div.className = 'file-item';
      div.id = 'fileItem-' + i;
      const statusText = results[i] ? 'done' : 'wait';
      div.innerHTML =
        '<span class="fnum">' + (i + 1) + '.</span>' +
        '<strong class="fname">' + f.name + '</strong>' +
        '<span class="fsize">' + formatSize(f.size) + '</span>' +
        '<div class="file-progress" id="fp-' + i + '"><div class="file-progress-fill" id="fpf-' + i + '"></div></div>' +
        '<span class="file-status ' + statusText + '" id="fstat-' + i + '">' + (statusText === 'done' ? '✓' : '⋯') + '</span>' +
