      const rw = $('resizeW'), rh = $('resizeH');
      if (p === 'web') { quality.value = 80; rw.value = 1200; rh.value = ''; $('qLabel').textContent = '80%'; }
      else if (p === 'print') { quality.value = 100; rw.value = 3000; rh.value = ''; $('qLabel').textContent = '100%'; }
      else if (p === 'ecom') { quality.value = 85; rw.value = 1000; rh.value = ''; $('qLabel').textContent = '85%'; }
