    for (let i = 0; i < files.length; i++) {
      statusText.textContent = 'Processing ' + (i + 1) + '/' + files.length + ': ' + files[i].name;
      progFill.style.width = ((i / files.length) * 100) + '%';

      const fstat = $('fstat-' + i);
      const fpf = $('fpf-' + i);
      const fcomp = $('fcomp-' + i);
      if (fstat) { fstat.className = 'file-status proc'; fstat.textContent = '⏳'; }
      if (fpf) fpf.style.width = '50%';

      const blob = await processOne(files[i], tW, tH, keepRatio, fmt, q, wmText, wmSize, wmAlpha, wmPos);

      if (fpf) fpf.style.width = '100%';
      if (fstat) { fstat.className = 'file-status done'; fstat.textContent = '✓'; }

      const origSize = originalSizes[i] || files[i].size;
      const newSize = blob.size;
      const ratio = origSize > 0 ? ((1 - newSize / origSize) * 100).toFixed(1) : 0;
      if (fcomp) {
        if (newSize < origSize) {
          fcomp.className = 'file-compare saved';
          fcomp.textContent = '-' + ratio + '%';
        } else {
          fcomp.className = 'file-compare nosave';
          fcomp.textContent = '+' + Math.abs(ratio) + '%';
        }
      }

      results.push({ name: files[i].name, blob });
    }

    progFill.style.width = '100%';
    statusText.textContent = 'Done! ' + results.length + ' images processed.';

    const totalOrig = originalSizes.reduce((a, b) => a + b, 0);
    const totalNew = results.reduce((a, r) => a + r.blob.size, 0);
    const totalSaved = totalOrig - totalNew;
    const compressPct = totalOrig > 0 ? ((1 - totalNew / totalOrig) * 100).toFixed(1) : 0;

    $('statOrig').textContent = formatSize(totalOrig);
    $('statProc').textContent = formatSize(totalNew);
    $('statSaved').textContent = formatSize(Math.abs(totalSaved)) + (totalSaved >= 0 ? ' saved' : ' larger');
    $('statCompress').textContent = (totalSaved >= 0 ? '-' : '+') + Math.abs(compressPct) + '%';
    $('statsBar').style.display = 'flex';

    processBtn.disabled = false;
    downloadBtn.disabled = false;
  }

  function processOne(file, tW, tH, keepRatio, fmt, q, wmText, wmSize, wmAlpha, wmPos) {
    return new Promise(resolve => {
      const reader = new FileReader();
      reader.onload = e => {
        const img = new Image();
        img.onload = () => {
          let w = img.width, h = img.height;
          if (tW && tH) { w = tW; h = tH; }
          else if (tW) { h = keepRatio ? Math.round(img.height * tW / img.width) : img.height; w = tW; }
          else if (tH) { w = keepRatio ? Math.round(img.width * tH / img.height) : img.width; h = tH; }

          const c = document.createElement('canvas');
          c.width = w; c.height = h;
          const ctx = c.getContext('2d');

          if (fmt === 'image/jpeg' || (!fmt || fmt === 'same' && file.type === 'image/jpeg')) {
            ctx.fillStyle = '#FFFFFF';
            ctx.fillRect(0, 0, w, h);
          }
          ctx.drawImage(img, 0, 0, w, h);

          if (wmText) {
            ctx.save();
            ctx.globalAlpha = wmAlpha;
            ctx.font = wmSize + 'px sans-serif';
            ctx.fillStyle = '#000';
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            const tw = ctx.measureText(wmText).width;
            const th = wmSize * 1.2;
            let wx = 20, wy = h - 20;
            if (wmPos === 'tl') { wx = 20; wy = th; }
            else if (wmPos === 'tr') { wx = w - tw - 20; wy = th; }
            else if (wmPos === 'bl') { wx = 20; wy = h - 20; }
            else if (wmPos === 'br') { wx = w - tw - 20; wy = h - 20; }
            else if (wmPos === 'center') { wx = w / 2 - tw / 2; wy = h / 2 + th / 4; }
            ctx.strokeText(wmText, wx, wy);
            ctx.fillText(wmText, wx, wy);
            ctx.restore();
          }

          const outFmt = fmt === 'same' ? (file.type || 'image/jpeg') : fmt;
          c.toBlob(blob => resolve(blob), outFmt, q);
        };
        img.src = e.target.result;
      };
      reader.readAsDataURL(file);
    });
  }

  /* ---------- Download ZIP ---------- */
  downloadBtn.addEventListener('click', async () => {
    if (!results.length) return;
