function makeICO(canvasArr) {
  // Minimal ICO: header(6) + entries(16 each) + PNG data
  const pngDatas = canvasArr.map(c => {
    const d = c.toDataURL('image/png').split(',')[1];
    return Uint8Array.from(atob(d), c => c.charCodeAt(0));
  });
  const header = new Uint8Array(6);
  header[0] = 0; header[1] = 0; // reserved
  header[2] = 1; header[3] = 0; // type=1 (ICO)
  header[4] = pngDatas.length & 0xff; header[5] = (pngDatas.length >> 8) & 0xff;
  let entriesLen = pngDatas.length * 16;
  let totalLen = 6 + entriesLen + pngDatas.reduce((a, b) => a + b.length, 0);
  const out = new Uint8Array(totalLen);
  out.set(header, 0);
  let dataOffset = 6 + entriesLen;
  pngDatas.forEach((png, i) => {
    const s = canvasArr[i].width;
    const off = 6 + i * 16;
    out[off] = s >= 256 ? 0 : s; // width (0=256)
    out[off+1] = s >= 256 ? 0 : s; // height
    out[off+2] = 0; // palette
    out[off+3] = 0; // reserved
    out[off+4] = 1; out[off+5] = 0; // color planes
    out[off+6] = 32; out[off+7] = 0; // bits per pixel
    const sz = png.length;
    out[off+8] = sz & 0xff; out[off+9] = (sz>>8)&0xff; out[off+10] = (sz>>16)&0xff; out[off+11] = (sz>>24)&0xff;
    out[off+12] = dataOffset & 0xff; out[off+13] = (dataOffset>>8)&0xff; out[off+14] = (dataOffset>>16)&0xff; out[off+15] = (dataOffset>>24)&0xff;
    out.set(png, dataOffset);
    dataOffset += sz;
  });
  return out;
}

