// === Helpers ===
function showStatus(msg, color) {
  statusMsg.textContent = msg;
  statusMsg.style.color = color || 'var(--text-secondary)';
}

// === Window resize ===
window.addEventListener('resize', () => {
  if (processedResult) {
    const boxW = previewBox.clientWidth - 32;
    const boxH = 500;
    let pW, pH;
    if (processedResult.width > processedResult.height) { pW = Math.min(boxW, processedResult.width); pH = pW * processedResult.height / processedResult.width; }
    else { pH = Math.min(boxH, processedResult.height); pW = pH * processedResult.width / processedResult.height; }
    previewCanvas.width = pW; previewCanvas.height = pH;
    const pCtx = previewCanvas.getContext('2d');
    pCtx.drawImage(processedResult, 0, 0, pW, pH);
  } else if (origImage) { updatePreviewSize(); }
});

