const dropzone = document.getElementById('dropzone');
    const fileInput = document.getElementById('fileInput');
    const previewArea = document.getElementById('previewArea');
    const resultImg = document.getElementById('resultImg');
    const radiusRange = document.getElementById('radiusRange');
    const borderWidthRange = document.getElementById('borderWidthRange');
    const radiusVal = document.getElementById('radiusVal');
    const borderVal = document.getElementById('borderVal');
    const borderColorPicker = document.getElementById('borderColorPicker');
    const bgColorPicker = document.getElementById('bgColorPicker');
    const borderColorHex = document.getElementById('borderColorHex');
    const bgColorHex = document.getElementById('bgColorHex');
    const applyBtn = document.getElementById('applyBtn');
    const downloadBtn = document.getElementById('downloadBtn');
    const resetBtn = document.getElementById('resetBtn');
    const status = document.getElementById('status');

    let currentFile = null;
    let originalImg = null;
    let resultBlob = null;
    let prevBlobUrl = null;

    setupDropzone({ dropzoneId: 'dropzone', inputId: 'fileInput', onFile: handleFile });

    radiusRange.addEventListener('input', () => { radiusVal.textContent = radiusRange.value + '%'; });
    borderWidthRange.addEventListener('input', () => { borderVal.textContent = borderWidthRange.value + 'px'; });
    borderColorPicker.addEventListener('input', () => { borderColorHex.textContent = borderColorPicker.value; });
    bgColorPicker.addEventListener('input', () => { bgColorHex.textContent = bgColorPicker.value; });

    function handleFile(file) {
      if (!file.type.startsWith('image/')) { status.textContent = 'Please select an image file.'; return; }
      currentFile = file;
      ImageUtils.load(file).then(async img => {
        originalImg = img;
        status.innerHTML = '<div class="spinner"></div>';
        try {
          await applyBorder();
        } catch(e) {
          status.textContent = 'Error: ' + e.message;
          return;
        }
        previewArea.classList.add('active');
        const bp = document.getElementById('beforeAfterPreview');
        if (bp) bp.classList.add('hidden');
        dropzone.classList.add('hidden');
        status.textContent = '';
        downloadBtn.classList.remove('hidden');
      }).catch(err => {
        status.textContent = 'Error loading image: ' + err.message;
      });
    }

    // Draw a rounded rectangle path on ctx
    function roundRect(ctx, x, y, w, h, r) {
      r = Math.min(r, w / 2, h / 2);
      ctx.beginPath();
      ctx.moveTo(x + r, y);
      ctx.lineTo(x + w - r, y);
      ctx.arcTo(x + w, y, x + w, y + r, r);
      ctx.lineTo(x + w, y + h - r);
      ctx.arcTo(x + w, y + h, x + w - r, y + h, r);
      ctx.lineTo(x + r, y + h);
      ctx.arcTo(x, y + h, x, y + h - r, r);
      ctx.lineTo(x, y + r);
      ctx.arcTo(x, y, x + r, y, r);
      ctx.closePath();
    }

    async function applyBorder() {
      if (!originalImg) return;
      const W = originalImg.naturalWidth;
      const H = originalImg.naturalHeight;
      const borderW = parseInt(borderWidthRange.value);
      const radiusPct = parseInt(radiusRange.value) / 100;
      const radius = Math.round(Math.min(W, H) * radiusPct);
      const borderColor = borderColorPicker.value;
      const bgColor = bgColorPicker.value;

      const canvas = ImageUtils.createCanvas(W, H);
      const ctx = canvas.getContext('2d');

      // Step 1: fill entire canvas with background color
      ctx.fillStyle = bgColor;
      ctx.fillRect(0, 0, W, H);

      // Step 2: draw border (filled rounded rect behind image)
      if (borderW > 0) {
        ctx.fillStyle = borderColor;
        roundRect(ctx, 0, 0, W, H, radius);
        ctx.fill();
      }

      // Step 3: clip to inner rounded rect and draw image
      ctx.save();
      roundRect(ctx, borderW, borderW, W - borderW * 2, H - borderW * 2, Math.max(0, radius - borderW));
      ctx.clip();
      ctx.drawImage(originalImg, borderW, borderW, W - borderW * 2, H - borderW * 2);
      ctx.restore();

      const blob = await ImageUtils.canvasToBlob(canvas, 'image/png');
      if (prevBlobUrl) { try { URL.revokeObjectURL(prevBlobUrl); } catch(e) {} }
      const url = URL.createObjectURL(blob);
      prevBlobUrl = url;
      resultBlob = blob;
      resultImg.src = url;
      return blob;
    }

