.prev-item .info{flex:1;min-width:200px}
.prev-item .info p{margin:0.25rem 0;font-size:0.85rem;color:#374151}
.prev-item .badge{display:inline-block;padding:2px 8px;border-radius:12px;font-size:0.75rem;font-weight:600}
.badge-saved{background:#dcfce7;color:#166534}
.badge-larger{background:#fee2e2;color:#991b1b}
.prev-item button{background:none;border:none;cursor:pointer;font-size:1.1rem;color:#ef4444;padding:4px 8px}
.controls{display:flex;flex-wrap:wrap;gap:1rem;align-items:center;justify-content:center;margin:1rem 0}
.controls label{font-weight:600;font-size:0.9rem}
.controls input[type=range]{width:120px}
.controls select,.controls input[type=number]{padding:6px 10px;border:1px solid #ccc;border-radius:6px;font-size:0.9rem}
.btn{padding:10px 22px;border:none;border-radius:8px;font-size:0.95rem;cursor:pointer;font-weight:600;transition:all .2s}
.btn-primary{background:#4f46e5;color:#fff}
.btn-primary:hover{background:#4338ca}
.btn-secondary{background:#e5e7eb;color:#1f2937}
.btn-secondary:hover{background:#d1d5db}
.btn:disabled{opacity:0.5;cursor:not-allowed}
.status{text-align:center;padding:0.75rem;font-size:0.9rem;color:#6b7280}
.progress-bar{width:100%;height:8px;background:#e5e7eb;border-radius:4px;overflow:hidden;margin:0.5rem 0}
.progress-fill{height:100%;background:#4f46e5;transition:width 0.3s}
.compare-wrap{display:flex;gap:1.5rem;flex-wrap:wrap;justify-content:center;margin:1rem 0}
.compare-box{flex:1;min-width:200px;text-align:center}
.compare-box img{max-width:100%;border-radius:8px;border:1px solid #e5e7eb}
.compare-box p{margin:0.5rem 0;font-size:0.85rem;color:#6b7280}

