const $ = id => document.getElementById(id);
const fileInput = $('fileInput'), uploadArea = $('uploadArea'), workspace = $('workspace');
const previewList = $('previewList'), compressBtn = $('compressBtn'), downloadAllBtn = $('downloadAllBtn');
const addMoreBtn = $('addMoreBtn'), clearBtn = $('clearBtn');
const progBar = $('progBar'), progFill = $('progFill'), statusText = $('statusText');
const qualityRange = $('qualityRange'), qualityVal = $('qualityVal'), maxWidth = $('maxWidth'), outputFmt = $('outputFmt');

let images = []; // { name, file, url, compressedUrl, compressedBlob, originalSize, compressedSize }

qualityRange.addEventListener('input', () => { qualityVal.textContent = qualityRange.value; });

// Upload
uploadArea.addEventListener('click', () => fileInput.click());
uploadArea.addEventListener('dragover', e => { e.preventDefault(); uploadArea.style.borderColor = '#4f46e5'; });
uploadArea.addEventListener('dragleave', () => { uploadArea.style.borderColor = '#d1d5db'; });
uploadArea.addEventListener('drop', e => {
  e.preventDefault(); uploadArea.style.borderColor = '#d1d5db';
  addFiles(Array.from(e.dataTransfer.files).filter(f => f.type.startsWith('image/')));
});
fileInput.addEventListener('change', () => { addFiles(Array.from(fileInput.files).filter(f => f.type.startsWith('image/'))); fileInput.value = ''; });

function addFiles(arr) {
  if (!arr.length) return;
  images = images.concat(arr.map(f => ({ name: f.name, file: f, url: URL.createObjectURL(f), compressedUrl: null, compressedBlob: null, originalSize: f.size, compressedSize: 0 })));
  uploadArea.style.display = 'none';
  workspace.style.display = 'block';
  renderList();
}

function formatSize(bytes) {
  if (bytes < 1024) return bytes + ' B';
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
  return (bytes / (1024 * 1024)).toFixed(2) + ' MB';
}

function renderList() {
  previewList.innerHTML = '';
  images.forEach((item, i) => {
    const div = document.createElement('div');
    div.className = 'prev-item';
    const hasCompressed = item.compressedUrl;
    const pct = hasCompressed && item.originalSize > 0 ? Math.round((1 - item.compressedSize / item.originalSize) * 100) : 0;
    const badge = hasCompressed ? (pct > 0 ? `<span class="badge badge-saved">-${pct}% hemat</span>` : `<span class="badge badge-larger">+${Math.abs(pct)}% lebih besar</span>`) : '';
    const fmt = outputFmt.value === 'same' ? item.file.type : outputFmt.value;
    const ext = fmt === 'image/png' ? '.png' : fmt === 'image/webp' ? '.webp' : '.jpg';
    const outName = item.name.replace(/\.(jpg|jpeg|png|webp)$/i, '') + (hasCompressed ? ext : '');

    div.innerHTML = `
      <img class="thumb" src="${item.url}">
      <div class="info">
        <p><strong>${item.name}</strong> ${badge}</p>
        <p>Original: ${formatSize(item.originalSize)}</p>
        ${hasCompressed ? `<p>Terompres: ${formatSize(item.compressedSize)}</p>` : '<p>Belum diompres</p>'}
      </div>
      ${hasCompressed ? `<a href="${item.compressedUrl}" download="${outName}" class="btn btn-secondary" style="padding:4px 10px;font-size:0.8rem;align-self:center">Unduh</a>` : ''}
      <button title="Hapus" style="align-self:flex-start">✕</button>`;
    div.querySelector('button').addEventListener('click', e => { e.stopPropagation(); URL.revokeObjectURL(item.url); if (item.compressedUrl) URL.revokeObjectURL(item.compressedUrl); images.splice(i, 1); renderList(); });
    previewList.appendChild(div);
  });
  downloadAllBtn.style.display = images.some(i => i.compressedUrl) && images.filter(i => i.compressedUrl).length > 1 ? 'inline-block' : 'none';
}

addMoreBtn.addEventListener('click', () => fileInput.click());

compressBtn.addEventListener('click', async () => {
  if (!images.length) return;
  compressBtn.disabled = true;
  progBar.style.display = 'block';

  const quality = parseInt(qualityRange.value) / 100;
  const maxW = parseInt(maxWidth.value) || undefined;

  for (let i = 0; i < images.length; i++) {
    if (images[i].compressedUrl) { // already compressed
      progFill.style.width = (((i +1) / images.length) * 100) + '%';
      continue;
    }
    statusText.textContent = `Mengompresi ${i+1}/${images.length}: ${images[i].name}...`;
    progFill.style.width = ((i / images.length) * 100) + '%';

    try {
      const options = {
        maxSizeMB: Infinity, // we control via quality
        initialQuality: quality,
        useWebWorker: true,
        onProgress: p => { progFill.style.width = ((i + p) / images.length * 100) + '%'; }
      };
      if (maxW) options.maxWidthOrHeight = maxW;

      // browser-image-compression expects a File object
      let fileToCompress = images[i].file;
      // If output format differs, we need to re-encode — the library handles this via `fileType` option
      if (outputFmt.value !== 'same') options.fileType = outputFmt.value;

      const compressedFile = await imageCompression(fileToCompress, options);
      images[i].compressedBlob = compressedFile;
      images[i].compressedSize = compressedFile.size;
      images[i].compressedUrl = URL.createObjectURL(compressedFile);
    } catch (err) {
      statusText.textContent = `Error mengompresi ${images[i].name}: ${err.message}`;
      console.error(err);
    }
  }

  progFill.style.width = '100%';
  const totalOriginal = images.reduce((s, i) => s + i.originalSize,0);
  const totalCompressed = images.filter(i => i.compressedUrl).reduce((s, i) => s + i.compressedSize,0);
  statusText.textContent = `Selesai! Total hemat: ${formatSize(totalOriginal)} → ${formatSize(totalCompressed)}`;
  setTimeout(() => { progBar.style.display = 'none'; statusText.textContent = ''; }, 4000);
  compressBtn.disabled = false;
  renderList();
});

downloadAllBtn.addEventListener('click', async () => {
  const zip = new JSZip();
  images.forEach(item => {
    if (item.compressedBlob) {
      const fmt = outputFmt.value === 'same' ? item.file.type : outputFmt.value;
      const ext = fmt === 'image/png' ? '.png' : fmt === 'image/webp' ? '.webp' : '.jpg';
      const outName = item.name.replace(/\.(jpg|jpeg|png|webp)$/i, '') + ext;
      zip.file(outName, item.compressedBlob);
    }
  });
  statusText.textContent = 'Membuat ZIP...';
  const blob = await zip.generateAsync({ type: 'blob' });
  const a = document.createElement('a');
  a.download = 'gambar-terompres.zip';
  a.href = URL.createObjectURL(blob);
  a.click();
  URL.revokeObjectURL(a.href);
  statusText.textContent = 'ZIP terunduh!';
  setTimeout(() => { statusText.textContent = ''; }, 2000);
});

clearBtn.addEventListener('click', () => {
  images.forEach(f => { URL.revokeObjectURL(f.url); if (f.compressedUrl) URL.revokeObjectURL(f.compressedUrl); });
  images = [];
  previewList.innerHTML = '';
  workspace.style.display = 'none'; uploadArea.style.display = 'block';
  progBar.style.display = 'none'; statusText.textContent = '';
});

let origImage = null;
let origImageData = null;
let canvas = document.getElementById('previewCanvas');
let ctx = canvas.getContext('2d');
let beforeCanvas, afterCanvas;
let isComparing = false;

// File handling
const dropzone = document.getElementById('dropzone');
const fileInput = document.getElementById('fileInput');
dropzone.addEventListener('dragover', e => { e.preventDefault(); dropzone.classList.add('drag'); });
dropzone.addEventListener('dragleave', () => dropzone.classList.remove('drag'));
dropzone.addEventListener('drop', e => {
  e.preventDefault(); dropzone.classList.remove('drag');
  if (e.dataTransfer.files[0]) handleFile(e.dataTransfer.files[0]);
});
fileInput.addEventListener('change', e => { if (e.target.files[0]) handleFile(e.target.files[0]); });

function handleFile(file) {
  if (!file.type.startsWith('image/')) { alert('Please select an image file.'); return; }
  const reader = new FileReader();
  reader.onload = e => {
    const img = new Image();
    img.onload = () => {
      origImage = img;
      canvas.width = img.width; canvas.height = img.height;
      ctx.drawImage(img, 0, 0);
      origImageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      canvas.style.display = 'block';
      document.getElementById('placeholderText').style.display = 'none';
      document.getElementById('downloadBtn').disabled = false;
      document.getElementById('resetBtn').disabled = false;
      resetSliders();
    };
    img.src = e.target.result;
  };
  reader.readAsDataURL(file);
}

function applyFilters() {
  if (!origImage || !origImageData) return;
  ctx.putImageData(origImageData, 0, 0);
  const bright = parseInt(document.getElementById('brightSlider').value);
  const contrast = parseInt(document.getElementById('contrastSlider').value);
  const saturate = parseInt(document.getElementById('saturateSlider').value);
  const exposure = parseInt(document.getElementById('exposureSlider').value);
  const highlights = parseInt(document.getElementById('highlightsVal').textContent);
  let filters = [];
  if (bright !== 0) filters.push(`brightness(${100 + bright}%)`);
  if (contrast !== 0) filters.push(`contrast(${100 + contrast}%)`);
  if (saturate !== 0) filters.push(`saturate(${100 + saturate}%)`);
  if (filters.length > 0) {
    ctx.filter = filters.join(' ');
    ctx.drawImage(origImage, 0, 0);
    ctx.filter = 'none';
  }
  // Sharpen via convolution
  const sharpenVal = parseInt(document.getElementById('sharpenSlider').value);
  if (sharpenVal > 0) applySharpen(sharpenVal / 100);
}

function applySharpen(amount) {
  const w = canvas.width, h = canvas.height;
  const src = ctx.getImageData(0, 0, w, h);
  const dst = ctx.createImageData(w, h);
  const k = amount * 0.8;
  const kernel = [0, -k, 0, -k, 1 + 4*k, -k, 0, -k, 0];
  for (let y = 1; y < h - 1; y++) {
    for (let x = 1; x < w - 1; x++) {
      for (let c = 0; c < 3; c++) {
        let val = 0;
        let ki = 0;
        for (let dy = -1; dy <= 1; dy++) {
          for (let dx = -1; dx <= 1; dx++) {
            val += src.data[((y+dy)*w + (x+dx))*4 + c] * kernel[ki];
            ki++;
          }
        }
        dst.data[(y*w+x)*4+c] = Math.max(0, Math.min(255, val));
      }
      dst.data[(y*w+x)*4+3] = src.data[(y*w+x)*4+3];
    }
  }
  ctx.putImageData(dst, 0, 0);
}

function onSliderChange() {
  document.getElementById('brightVal').textContent = document.getElementById('brightSlider').value;
  document.getElementById('contrastVal').textContent = document.getElementById('contrastSlider').value;
  document.getElementById('saturateVal').textContent = document.getElementById('saturateSlider').value;
  document.getElementById('sharpenVal').textContent = document.getElementById('sharpenSlider').value;
  document.getElementById('exposureVal').textContent = document.getElementById('exposureSlider').value;
  applyFilters();
  if (isComparing) updateCompare();
}

function resetSliders() {
  ['bright','contrast','saturate','sharpen','exposure','highlights'].forEach(id => {
    document.getElementById(id + 'Slider').value = 0;
    document.getElementById(id + 'Val').textContent = '0';
  });
  applyFilters();
}

function resetAll() {
  resetSliders();
  if (origImage) {
    ctx.drawImage(origImage, 0, 0);
    origImageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
  }
}

function applyPreset(name) {
  const presets = {
    'auto':    { bright:15, contrast:20, saturate:25, sharpen:40, exposure:10, highlights:-10 },
    'portrait': { bright:10, contrast:15, saturate:20, sharpen:30, exposure:5, highlights:-15 },
    'landscape':{ bright:5, contrast:25, saturate:35, sharpen:50, exposure:0, highlights:-5 },
    'vivid':   { bright:10, contrast:30, saturate:60, sharpen:35, exposure:5, highlights:0 },
    'warm':    { bright:10, contrast:10, saturate:30, sharpen:20, exposure:15, highlights:-10 },
    'cool':    { bright:5, contrast:15, saturate:-10, sharpen:20, exposure:0, highlights:0 }
  };
  const p = presets[name];
  if (!p) return;
  document.getElementById('brightSlider').value = p.bright;
  document.getElementById('contrastSlider').value = p.contrast;
  document.getElementById('saturateSlider').value = p.saturate;
  document.getElementById('sharpenSlider').value = p.sharpen;
  document.getElementById('exposureSlider').value = p.exposure;
  document.getElementById('highlightsSlider').value = p.highlights;
  onSliderChange();
}

function toggleCompare() {
  isComparing = document.getElementById('compareToggle').checked;
  document.getElementById('compareBox').style.display = isComparing ? 'block' : 'none';
  if (isComparing) setupCompare();
}

function setupCompare() {
  beforeCanvas = document.getElementById('beforeCanvas');
  afterCanvas = document.getElementById('afterCanvas');
  if (!origImage) return;
  const maxW = 800, maxH = 600;
  let w = origImage.width, h = origImage.height;
  if (w > maxW) { h = h * maxW / w; w = maxW; }
  if (h > maxH) { w = w * maxH / h; h = maxH; }
  beforeCanvas.width = afterCanvas.width = w;
  beforeCanvas.height = afterCanvas.height = h;
  const bCtx = beforeCanvas.getContext('2d');
  bCtx.drawImage(origImage, 0, 0, w, h);
  updateCompare();
  // Slider drag
  const box = document.getElementById('compareBox');
  let dragging = false;
  box.addEventListener('mousedown', e => { dragging = true; moveSlider(e); });
  document.addEventListener('mousemove', e => { if (dragging) moveSlider(e); });
  document.addEventListener('mouseup', () => dragging = false);
}

function moveSlider(e) {
  const box = document.getElementById('compareBox');
  const rect = box.getBoundingClientRect();
  let x = e.clientX - rect.left;
  x = Math.max(0, Math.min(rect.width, x));
  afterCanvas.style.clipPath = `inset(0 ${rect.width - x}px 0 0)`;
  document.getElementById('sliderHandle').style.left = x + 'px';
}

function updateCompare() {
  if (!afterCanvas || !origImage) return;
  const aCtx = afterCanvas.getContext('2d');
  aCtx.drawImage(origImage, 0, 0, afterCanvas.width, afterCanvas.height);
  // Redraw current filters to a temp canvas
  const tempCanvas = document.createElement('canvas');
  tempCanvas.width = afterCanvas.width; tempCanvas.height = afterCanvas.height;
  const tCtx = tempCanvas.getContext('2d');
  tCtx.drawImage(origImage, 0, 0, tempCanvas.width, tempCanvas.height);
  // Apply filters
  const bright = parseInt(document.getElementById('brightSlider').value);
  const contrast = parseInt(document.getElementById('contrastSlider').value);
  const saturate = parseInt(document.getElementById('saturateSlider').value);
  let filters = [];
  if (bright !== 0) filters.push(`brightness(${100+bright}%)`);
  if (contrast !== 0) filters.push(`contrast(${100+contrast}%)`);
  if (saturate !== 0) filters.push(`saturate(${100+saturate}%)`);
  if (filters.length > 0) {
    tCtx.filter = filters.join(' ');
    tCtx.drawImage(origImage, 0, 0, tempCanvas.width, tempCanvas.height);
  }
  aCtx.clearRect(0, 0, afterCanvas.width, afterCanvas.height);
  aCtx.drawImage(tempCanvas, 0, 0);
}

function downloadImage() {
  const link = document.createElement('a');
  link.download = 'enhanced-image.png';
  link.href = canvas.toDataURL('image/png');
  link.click();
}

const dropzone = document.getElementById('dropzone');
    const fileInput = document.getElementById('fileInput');
    const previewArea = document.getElementById('previewArea');
    const resultImg = document.getElementById('resultImg');
    const exifStatus = document.getElementById('exifStatus');
    const exifInfo = document.getElementById('exifInfo');
    const applyBtn = document.getElementById('applyBtn');
    const downloadBtn = document.getElementById('downloadBtn');
    const resetBtn = document.getElementById('resetBtn');
    const status = document.getElementById('status');

    let currentFile = null;
    let originalImg = null;
    let resultBlob = null;
    let prevBlobUrl = null;

    setupDropzone({ dropzoneId: 'dropzone', inputId: 'fileInput', onFile: handleFile });

    // Simple EXIF detection for JPEG files
    async function detectExif(file) {
      if (!file.type.includes('jpeg') && !file.name.match(/\.jpe?g$/i)) {
        return { hasExif: false, info: 'Not a JPEG file — no EXIF data possible.' };
      }
      try {
        const buf = await file.arrayBuffer();
        const view = new DataView(buf);
        if (view.getUint16(0) !== 0xFFD8) {
          return { hasExif: false, info: 'Not a valid JPEG file.' };
        }
        let offset = 2;
        let exifFound = false;
        let gpsFound = false;
        const tags = [];
        while (offset < buf.byteLength - 1) {
          if (view.getUint8(offset) !== 0xFF) break;
          const marker = view.getUint8(offset + 1);
          if (marker === 0xE1) { // APP1 — EXIF
            exifFound = true;
            const len = view.getUint16(offset + 2);
            const exifStart = offset + 4;
            const exifHeader = String.fromCharCode(...new Uint8Array(buf, exifStart, 6));
            if (exifHeader.includes('Exif')) {
              tags.push('EXIF block detected');
              // Try to read some EXIF tags
              try {
                const exifBuf = new Uint8Array(buf, exifStart, len - 2);
                const tagInfo = parseBasicExif(exifBuf);
                if (tagInfo.gps) gpsFound = true;
                tags.push(...tagInfo.tags);
              } catch(e) {}
            }
          }
          if (marker === 0xDA) break; // SOS — image data starts
          const segLen = view.getUint16(offset + 2);
          offset += 2 + segLen;
        }
        if (!exifFound) {
          return { hasExif: false, info: 'No EXIF data found in this image.' };
        }
        let msg = '<span class="exif-warn">⚠️ EXIF metadata detected:</span><br>';
        tags.forEach(t => { msg += '• ' + t + '<br>'; });
        if (gpsFound) msg += '<br><span class="exif-warn">⚠️ GPS location data found — remove it to protect your privacy!</span>';
        return { hasExif: true, info: msg };
      } catch(e) {
        return { hasExif: false, info: 'Could not read file metadata.' };
      }
    }

    function parseBasicExif(buf) {
      const tags = [];
      let gps = false;
      try {
        // Very basic: look for ASCII strings in EXIF data
        const str = String.fromCharCode(...buf);
        if (str.includes('GPS')) { gps = true; tags.push('GPS location data'); }
        if (str.match(/[A-Za-z]{3,}/)) { tags.push('Camera/software info present'); }
      } catch(e) {}
      return { tags, gps };
    }

    async function handleFile(file) {
      if (!file.type.startsWith('image/')) { status.textContent = 'Please select an image file.'; return; }
      currentFile = file;
      ImageUtils.load(file).then(async img => {
        originalImg = img;
        status.innerHTML = '<div class="spinner"></div> Checking metadata...';
        const exif = await detectExif(file);
        if (exif.hasExif) {
          exifInfo.innerHTML = exif.info;
          exifStatus.style.display = 'block';
        } else {
          exifInfo.innerHTML = '<span class="exif-clear">✅ No EXIF metadata detected. Your image is already clean.</span>';
          exifStatus.style.display = 'block';
        }
        previewArea.classList.add('active');
        const bp = document.getElementById('beforeAfterPreview');
        if (bp) bp.classList.add('hidden');
        dropzone.classList.add('hidden');
        status.textContent = 'Click "Remove EXIF" to strip metadata.';
        downloadBtn.classList.add('hidden');
      }).catch(err => {
        status.textContent = 'Error loading image: ' + err.message;
      });
    }

    async function removeExif() {
      if (!originalImg) return;
      const W = originalImg.naturalWidth;
      const H = originalImg.naturalHeight;
      const canvas = ImageUtils.createCanvas(W, H);
      const ctx = canvas.getContext('2d');
      ctx.drawImage(originalImg, 0, 0);

      const blob = await ImageUtils.canvasToBlob(canvas, 'image/png');
      if (prevBlobUrl) { try { URL.revokeObjectURL(prevBlobUrl); } catch(e) {} }
      const url = URL.createObjectURL(blob);
      prevBlobUrl = url;
      resultBlob = blob;
      resultImg.src = url;
      return blob;
    }

    applyBtn.addEventListener('click', async function() {
      if (!originalImg) return;
      applyBtn.disabled = true;
      applyBtn.textContent = '🔄 Removing...';
      status.innerHTML = '<div class="spinner"></div>';
      try {
        await removeExif();
        exifInfo.innerHTML = '<span class="exif-clear">✅ EXIF metadata successfully removed! The image is now clean.</span>';
        status.textContent = 'Done! Click Download to save the clean image.';
        downloadBtn.classList.remove('hidden');
      } catch (err) {
        status.textContent = 'Error: ' + err.message;
      } finally {
        applyBtn.disabled = false;
        applyBtn.textContent = '🗑️ Remove EXIF';
      }
    });

    downloadBtn.addEventListener('click', function() {
      if (resultBlob) {
        const base = (currentFile.name || 'image').replace(/\.[^.]+$/, '');
        ImageUtils.download(resultBlob, base + '-clean.png');
        try { SmartImgNextStep.show(); } catch(e) {}
      }
    });

    resetBtn.addEventListener('click', function() {
      if (prevBlobUrl) { try { URL.revokeObjectURL(prevBlobUrl); } catch(e) {} }
      prevBlobUrl = null;
      currentFile = null;
      originalImg = null;
      resultBlob = null;
      previewArea.classList.remove('active');
      const bp = document.getElementById('beforeAfterPreview');
      if (bp) bp.classList.remove('hidden');
      dropzone.classList.remove('hidden');
      fileInput.value = '';
      status.textContent = '';
      downloadBtn.classList.add('hidden');
      resultImg.src = '';
      exifStatus.style.display = 'none';
      exifInfo.textContent = '';
    });

    (function() {
      var _handleFile = typeof handleFile === 'function' ? handleFile : null;
      if (_handleFile) {
        window.initSampleButton('https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800&q=80', _handleFile);
      }
    })();

// ===== State =====
    let originalImg = null;
    let activePreset = 'none';

    // ===== DOM =====
    const dropzone = document.getElementById('dropzone');
    const fileInput = document.getElementById('fileInput');
    const workspace = document.getElementById('workspace');
    const canvas = document.getElementById('previewCanvas');
    const ctx = canvas.getContext('2d');

