    async function applyShadow() {
      if (!originalImg) return;
      const W = originalImg.naturalWidth;
      const H = originalImg.naturalHeight;
      const offX = parseInt(offsetXRange.value);
      const offY = parseInt(offsetYRange.value);
      const blurPx = parseInt(blurRange.value);
      const shadowColor = shadowColorPicker.value;

      // Determine background color
      let bgColor = '#ffffff';
      if (bgType === 'transparent') { bgColor = null; }
      else if (bgType === 'custom') { bgColor = bgColorPicker.value; }

      // Canvas size: expand to fit shadow
      const pad = blurPx * 2 + Math.max(Math.abs(offX), Math.abs(offY));
      const cw = W + pad * 2;
      const ch = H + pad * 2;
      const dx = pad;
      const dy = pad;

      const canvas = ImageUtils.createCanvas(cw, ch);
      const ctx = canvas.getContext('2d');

      // Fill background
      if (bgColor) {
        ctx.fillStyle = bgColor;
        ctx.fillRect(0, 0, cw, ch);
      }

      // Draw image with shadow
      ctx.shadowColor = shadowColor;
      ctx.shadowBlur = blurPx;
      ctx.shadowOffsetX = offX;
      ctx.shadowOffsetY = offY;
      ctx.drawImage(originalImg, dx, dy, W, H);

      const blob = await ImageUtils.canvasToBlob(canvas, 'image/png');
      if (prevBlobUrl) { try { URL.revokeObjectURL(prevBlobUrl); } catch(e) {} }
      const url = URL.createObjectURL(blob);
