      if (_handleFile) {
        window.initSampleButton('https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800&q=80', _handleFile);
      }
    })();

const $ = id => document.getElementById(id);
const fileInput = $('fileInput'), uploadArea = $('uploadArea'), workspace = $('workspace');
const previewList = $('previewList'), convertBtn = $('convertBtn');
const addMoreBtn = $('addMoreBtn'), clearBtn = $('clearBtn');
const progBar = $('progBar'), progFill = $('progFill'), statusText = $('statusText');

let images = []; // { name, dataUrl, width, height, el }

// Upload
uploadArea.addEventListener('click', () => fileInput.click());
uploadArea.addEventListener('dragover', e => { e.preventDefault(); uploadArea.style.borderColor = '#4f46e5'; });
uploadArea.addEventListener('dragleave', () => { uploadArea.style.borderColor = '#d1d5db'; });
uploadArea.addEventListener('drop', e => {
  e.preventDefault(); uploadArea.style.borderColor = '#d1d5db';
  addFiles(Array.from(e.dataTransfer.files).filter(f => f.type.startsWith('image/')));
});
fileInput.addEventListener('change', () => { addFiles(Array.from(fileInput.files)); fileInput.value = ''; });

function addFiles(arr) {
  if (!arr.length) return;
  let loaded = 0;
  arr.forEach(f => {
    const reader = new FileReader();
    reader.onload = e => {
      const img = new Image();
      img.onload = () => {
        images.push({ name: f.name, dataUrl: e.target.result, width: img.width, height: img.height, img });
        loaded++;
        if (loaded === arr.length) renderList();
      };
      img.src = e.target.result;
    };
    reader.readAsDataURL(f);
  });
  uploadArea.style.display = 'none';
  workspace.style.display = 'block';
}

function renderList() {
  previewList.innerHTML = '';
  images.forEach((item, i) => {
    const div = document.createElement('div');
    div.className = 'prev-item';
    div.draggable = true;
    div.innerHTML = `<span style="width:2rem;color:#9ca3af">${i+1}</span>
      <canvas id="prevCvs${i}"></canvas>
      <span>${item.name}</span>
      <button title="Remove">✕</button>`;
    // draw thumbnail
    const cv = div.querySelector('canvas');
    const scale = 60 / item.height;
    cv.width = Math.round(item.width * scale);
    cv.height = 60;
    cv.getContext('2d').drawImage(item.img, 0, 0, cv.width, cv.height);
    // remove
    div.querySelector('button').addEventListener('click', e => { e.stopPropagation(); images.splice(i, 1); renderList(); });
    // drag reorder
    div.addEventListener('dragstart', ev => ev.dataTransfer.setData('text/plain', i));
    div.addEventListener('dragover', ev => ev.preventDefault());
    div.addEventListener('drop', ev => {
      ev.preventDefault();
      const from = parseInt(ev.dataTransfer.getData('text/plain'));
      const to = i;
      if (from !== to) { images.splice(to, 0, images.splice(from, 1)[0]); renderList(); }
    });
    previewList.appendChild(div);
  });
}

addMoreBtn.addEventListener('click', () => fileInput.click());

convertBtn.addEventListener('click', async () => {
  if (!images.length) return;
  convertBtn.disabled = true;
  progBar.style.display = 'block';
  statusText.textContent = 'Generating PDF...';

  const { jsPDF } = window.jspdf;
  const isA4 = $('pageSize').value === 'a4';
  const isLetter = $('pageSize').value === 'letter';
  const margin = parseInt($('margin').value) || 20;

  let pdf;
  for (let i = 0; i < images.length; i++) {
    progFill.style.width = ((i / images.length) * 100) + '%';
    statusText.textContent = `Processing image ${i+1}/${images.length}...`;

    await new Promise(resolve => {
      const img = new Image();
      img.onload = () => {
        let w = img.width, h = img.height;
        let pw, ph;
        if (isA4) { pw = 595.28; ph = 841.89; }
        else if (isLetter) { pw = 612; ph = 792; }
        else { pw = w + margin * 2; ph = h + margin * 2; }

        if (!pdf) { pdf = new jsPDF({ orientation: w > h ? 'l' : 'p', unit: 'pt', format: [pw, ph] }); }
        else pdf.addPage([pw, ph], w > h ? 'l' : 'p');

        const scale = Math.min((pw - margin * 2) / w, (ph - margin * 2) / h);
        const dw = w * scale, dh = h * scale;
        const dx = (pw - dw) / 2, dy = (ph - dh) / 2;
        pdf.addImage(img, 'JPEG', dx, dy, dw, dh);
        resolve();
      };
      img.src = images[i].dataUrl;
    });
  }

  progFill.style.width = '100%';
  statusText.textContent = 'Done! Downloading...';
  pdf.save('images.pdf');
  setTimeout(() => { progBar.style.display = 'none'; progFill.style.width = '0%'; statusText.textContent = ''; convertBtn.disabled = false; }, 2000);
});

clearBtn.addEventListener('click', () => {
  images = []; previewList.innerHTML = '';
  workspace.style.display = 'none'; uploadArea.style.display = 'block';
});

// ===== State =====
    let originalImg = null;
    let scaleFactor = 2;

    // ===== DOM =====
    const dropzone = document.getElementById('dropzone');
    const fileInput = document.getElementById('fileInput');
    const workspace = document.getElementById('workspace');
    const previewCanvas = document.getElementById('previewCanvas');
    const ctx = previewCanvas.getContext('2d');
    const sharpenSlider = document.getElementById('sharpenSlider');
    const sharpenValue = document.getElementById('sharpenValue');
    const origDim = document.getElementById('origDim');
    const newDim = document.getElementById('newDim');
    const outputFormat = document.getElementById('outputFormat');
    const upscaleBtn = document.getElementById('upscaleBtn');
    const resetBtn = document.getElementById('resetBtn');
    const status = document.getElementById('status');

    // ===== Upload =====
    setupDropzone({ dropzoneId: 'dropzone', inputId: 'fileInput', onFile: handleFile });

    async function handleFile(file) {
      if (!file.type.startsWith('image/')) return;
      originalImg = await ImageUtils.load(file);
      dropzone.classList.add('hidden');
      workspace.style.display = '';
      updateDims();
      renderPreview();
    }

    // ===== Scale Buttons =====
    document.querySelectorAll('.scale-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        document.querySelectorAll('.scale-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        scaleFactor = parseInt(btn.dataset.scale);
        updateDims();
        renderPreview();
      });
    });

    // ===== Sharpening =====
    sharpenSlider.addEventListener('input', () => {
      sharpenValue.textContent = sharpenSlider.value;
      renderPreview();
    });

    // ===== Dimension Display =====
    function updateDims() {
      if (!originalImg) return;
      const w = originalImg.naturalWidth;
      const h = originalImg.naturalHeight;
      origDim.textContent = `${w} × ${h}`;
      newDim.textContent = `${w * scaleFactor} × ${h * scaleFactor}`;
    }

    // ===== Preview Render =====
    function renderPreview() {
      if (!originalImg) return;
      const w = originalImg.naturalWidth;
      const h = originalImg.naturalHeight;
      const nw = w * scaleFactor;
      const nh = h * scaleFactor;

      previewCanvas.width = nw;
      previewCanvas.height = nh;

      // High-quality interpolation
      ctx.imageSmoothingEnabled = true;
      ctx.imageSmoothingQuality = 'high';
      ctx.drawImage(originalImg, 0, 0, nw, nh);

      // Apply unsharp mask sharpening
      const strength = parseInt(sharpenSlider.value) / 100;
      if (strength > 0) applySharpen(ctx, nw, nh, strength);
    }

    // ===== Unsharp Mask Sharpening =====
    function applySharpen(ctx, w, h, strength) {
      const imageData = ctx.getImageData(0, 0, w, h);
      const data = imageData.data;

      // Create blurred version
      const blurred = new Uint8ClampedArray(data.length);
      const kernel = [1, 2, 1, 2, 4, 2, 1, 2, 1];
      const kSum = 16;

      for (let y = 1; y < h - 1; y++) {
        for (let x = 1; x < w - 1; x++) {
          for (let c = 0; c < 3; c++) {
            let sum = 0;
            let ki = 0;
            for (let ky = -1; ky <= 1; ky++) {
              for (let kx = -1; kx <= 1; kx++) {
                const idx = ((y + ky) * w + (x + kx)) * 4 + c;
                sum += data[idx] * kernel[ki++];
              }
            }
            blurred[(y * w + x) * 4 + c] = sum / kSum;
          }
          blurred[(y * w + x) * 4 + 3] = data[(y * w + x) * 4 + 3];
        }
      }

      // Unsharp mask: sharpened = original + strength * (original - blurred)
      const amount = strength * 1.5; // max 1.5x sharpening
      for (let i = 0; i < data.length; i += 4) {
        for (let c = 0; c < 3; c++) {
          const diff = data[i + c] - blurred[i + c];
          data[i + c] = Math.min(255, Math.max(0, data[i + c] + diff * amount));
        }
      }

      ctx.putImageData(imageData, 0, 0);
    }

    // ===== Upscale & Download =====
    upscaleBtn.addEventListener('click', async () => {
      if (!originalImg) return;
      upscaleBtn.disabled = true;
      upscaleBtn.textContent = '🔄 Upscaling...';
      status.textContent = '';

      try {
        const format = outputFormat.value;
        const quality = format === 'image/png' ? undefined : 0.92;
        const blob = await ImageUtils.canvasToBlob(previewCanvas, format, quality);
        const ext = format === 'image/png' ? 'png' : format === 'image/jpeg' ? 'jpg' : 'webp';
        ImageUtils.download(blob, `upscaled-${scaleFactor}x.${ext}`);
        status.textContent = `✅ Image upscaled to ${scaleFactor}x and downloaded!`;
      } catch (e) {
        status.textContent = '❌ Error: ' + e.message;
      }

      upscaleBtn.disabled = false;
      upscaleBtn.textContent = '🔍 Upscale & Download';
    });

    // ===== Reset =====
    resetBtn.addEventListener('click', () => {
      originalImg = null;
      workspace.style.display = 'none';
      dropzone.classList.remove('hidden');
      fileInput.value = '';
      status.textContent = '';
    });

  // Sample image & Next Step
  (function() {
    var _handleFile = typeof handleFile === 'function' ? handleFile : null;
    if (_handleFile) {
      window.initSampleButton('https://images.unsplash.com/photo-1518173946687-a1e4e3e3f6be?w=800&q=80', _handleFile);
    }
    // Show next-step on download click
    var dlBtn = document.getElementById('downloadBtn') || document.querySelector('.btn-primary[onclick*="download"], .btn-secondary[onclick*="download"]');
    if (dlBtn) {
      dlBtn.addEventListener('click', function() { SmartImgNextStep.show(); });
    }
  })();

// ===== Template data (drawn on canvas, no external images needed) =====
    const TEMPLATES = {
      drake:        { name: 'Drake', draw: drawDrake },
      distracted:  { name: 'Distracted Boyfriend', draw: drawDistracted },
      womanyelling: { name: 'Woman Yelling', draw: drawWomanYelling },
      twobuttons:   { name: 'Two Buttons', draw: drawTwoButtons },
      changing:     { name: 'Change My Mind', draw: drawChangeMyMind },
    };

    // ===== State =====
    let bgImage = null; // background image (uploaded or template)
    let activeTemplate = null;

    // ===== DOM =====
    const dropzone = document.getElementById('dropzone');
    const fileInput = document.getElementById('fileInput');
    const templateSection = document.getElementById('templateSection');
    const templateGrid = document.getElementById('templateGrid');
    const workspace = document.getElementById('workspace');
    const canvas = document.getElementById('previewCanvas');
    const ctx = canvas.getContext('2d');

    const topTextInput = document.getElementById('topText');
    const bottomTextInput = document.getElementById('bottomText');
    const fontSizeSlider = document.getElementById('fontSize');
    const outlineSlider = document.getElementById('outlineWidth');
    const textCaseSelect = document.getElementById('textCase');
    const outputFormat = document.getElementById('outputFormat');

    // ===== Build template grid =====
    Object.entries(TEMPLATES).forEach(([key, tpl]) => {
      const btn = document.createElement('button');
      btn.className = 'template-btn';
      btn.dataset.template = key;
      btn.innerHTML = '<span style="font-size:.7rem;padding:4px 0;">' + tpl.name + '</span>';
      // Draw a tiny preview icon on a mini canvas
      const miniC = document.createElement('canvas');
      miniC.width = 80; miniC.height = 60;
      const mCtx = miniC.getContext('2d');
      tpl.draw(mCtx, 80, 60, '', '');
      btn.appendChild(miniC);
      btn.addEventListener('click', () => {
        document.querySelectorAll('.template-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        activeTemplate = key;
        // Create a blank bg image (we'll draw the template on render)
        bgImage = null;
        if (workspace.style.display !== 'none') renderPreview();
      });
      templateGrid.appendChild(btn);
    });

    // ===== File Upload =====
    setupDropzone({
      dropzoneId: 'dropzone',
      inputId: 'fileInput',
      onFile: async (file) => {
        try {
          bgImage = await ImageUtils.load(file);
          activeTemplate = null;
          document.querySelectorAll('.template-btn').forEach(b => b.classList.remove('active'));
          dropzone.style.display = 'none';
          templateSection.style.display = 'block';
          workspace.style.display = 'block';
          renderPreview();
        } catch (e) {
          ImageUtils.showToast('Failed to load image', 'error');
        }
      }
    });

    // ===== Text / Style Events =====
    [topTextInput, bottomTextInput].forEach(el => el.addEventListener('input', () => renderPreview()));
    [fontSizeSlider, outlineSlider, textCaseSelect].forEach(el => el.addEventListener('input', () => renderPreview()));

    // ===== Reset =====
    document.getElementById('resetBtn').addEventListener('click', () => {
      bgImage = null;
      activeTemplate = null;
      workspace.style.display = 'none';
      templateSection.style.display = 'none';
      dropzone.style.display = '';
      fileInput.value = '';
      topTextInput.value = '';
      bottomTextInput.value = '';
      fontSizeSlider.value = 60;
      outlineSlider.value = 6;
      textCaseSelect.value = 'uppercase';
      document.querySelectorAll('.template-btn').forEach(b => b.classList.remove('active'));
      document.getElementById('infoRow').style.display = 'none';
    });

    // ===== Download =====
    document.getElementById('downloadBtn').addEventListener('click', () => {
      const mime = outputFormat.value;
      const ext = mime === 'image/jpeg' ? 'jpg' : mime === 'image/webp' ? 'webp' : 'png';
      ImageUtils.download(canvas, 'meme.' + ext, mime);
      ImageUtils.showToast('Meme downloaded!');
    });

    // ===== Render =====
    function renderPreview() {
      const W = 800, H = 600; // standard meme canvas size
      canvas.width = W;
      canvas.height = H;
      ctx.clearRect(0, 0, W, H);

      // Draw background (template or uploaded image)
      if (activeTemplate && TEMPLATES[activeTemplate]) {
        TEMPLATES[activeTemplate].draw(ctx, W, H, topTextInput.value, bottomTextInput.value);
      } else if (bgImage) {
        // Fit uploaded image
        const ratio = Math.min(W / bgImage.width, H / bgImage.height);
        const dw = bgImage.width * ratio;
        const dh = bgImage.height * ratio;
        const dx = (W - dw) / 2;
        const dy = (H - dh) / 2;
        ctx.drawImage(bgImage, dx, dy, dw, dh);
        // Draw text over it
        drawMemeText(ctx, W, H, topTextInput.value, bottomTextInput.value);
      } else {
        // Nothing loaded yet
        ctx.fillStyle = '#000';
        ctx.fillRect(0, 0, W, H);
        drawMemeText(ctx, W, H, topTextInput.value, bottomTextInput.value);
      }

      document.getElementById('infoRow').style.display = 'flex';
      document.getElementById('outSize').textContent = W + ' x ' + H;
    }

    // ===== Draw meme text (outline style) =====
    function drawMemeText(ctx, W, H, topText, bottomText) {
      const fontSize = parseInt(fontSizeSlider.value);
      const outlineW = parseInt(outlineWidth.value);
      const textCase = textCaseSelect.value;

      function processText(t) {
        if (!t) return '';
        if (textCase === 'uppercase') return t.toUpperCase();
        if (textCase === 'capitalize') return t.replace(/\b\w/g, c => c.toUpperCase());
        return t;
      }

      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.font = 'bold ' + fontSize + 'px Impact, sans-serif';

      // Top text
      if (topText) {
        const txt = processText(topText);
        const y = fontSize + 20;
        ctx.lineWidth = outlineW;
        ctx.strokeStyle = '#000';
        ctx.fillStyle = '#fff';
        ctx.lineJoin = 'round';
        // Word wrap
        const lines = wrapText(ctx, txt, W - 40, fontSize);
        lines.forEach((line, i) => {
          const ly = y + i * (fontSize + 4);
          ctx.strokeText(line, W / 2, ly);
          ctx.fillText(line, W / 2, ly);
        });
      }

      // Bottom text
      if (bottomText) {
        const txt = processText(bottomText);
        ctx.lineWidth = outlineW;
        ctx.strokeStyle = '#000';
        ctx.fillStyle = '#fff';
        const lines = wrapText(ctx, txt, W - 40, fontSize);
        const totalH = lines.length * (fontSize + 4);
        const startY = H - totalH + fontSize;
        lines.forEach((line, i) => {
          const ly = startY + i * (fontSize + 4);
          ctx.strokeText(line, W / 2, ly);
          ctx.fillText(line, W / 2, ly);
        });
      }
    }

    function wrapText(ctx, text, maxWidth, fontSize) {
      const words = text.split(' ');
      const lines = [];
      let current = '';
      for (const word of words) {
        const test = current + (current ? ' ' : '') + word;
        if (ctx.measureText(test).width > maxWidth && current) {
          lines.push(current);
          current = word;
        } else {
          current = test;
        }
      }
      if (current) lines.push(current);
      return lines;
    }

    // ===== Template drawing functions (simplified representations) =====
    function drawDrake(ctx, W, H, top, bottom) {
      // Simple Drake meme: left = dislikes (top text), right = likes (bottom text)
      ctx.fillStyle = '#87ceeb';
      ctx.fillRect(0, 0, W, H);
      // Left side (dislikes)
      ctx.fillStyle = '#ddd';
      ctx.fillRect(0, 0, W/2, H);
      // Right side (likes)
      ctx.fillStyle = '#fff';
      ctx.fillRect(W/2, 0, W/2, H);
      // Simple figure representations
      ctx.fillStyle = '#8b4513';
      ctx.beginPath(); ctx.arc(W/4, H*0.6, 60, 0, Math.PI*2); ctx.fill(); // left head
      ctx.beginPath(); ctx.arc(W*3/4, H*0.6, 60, 0, Math.PI*2); ctx.fill(); // right head
      // Labels
      ctx.fillStyle = '#000';
      ctx.font = 'bold 24px Impact';
      ctx.textAlign = 'center';
      ctx.fillText('DISLIKES', W/4, 30);
      ctx.fillText('LIKES', W*3/4, 30);
      drawMemeText(ctx, W, H, top, bottom);
    }

    function drawDistracted(ctx, W, H, top, bottom) {
      ctx.fillStyle = '#f0e68c';
      ctx.fillRect(0, 0, W, H);
      // Three simple figures
      const colors = ['#4a90d9', '#d0021b', '#4a90d9'];
      colors.forEach((c, i) => {
        ctx.fillStyle = c;
        ctx.beginPath();
        ctx.arc(W*0.25 + i*W*0.25, H*0.55, 40, 0, Math.PI*2);
        ctx.fill();
      });
      drawMemeText(ctx, W, H, top, bottom);
    }

    function drawWomanYelling(ctx, W, H, top, bottom) {
      ctx.fillStyle = '#e8e8e8';
      ctx.fillRect(0, 0, W, H);
      // Woman (left)
      ctx.fillStyle = '#d0021b';
      ctx.beginPath(); ctx.arc(W*0.3, H*0.55, 50, 0, Math.PI*2); ctx.fill();
      // Cat (right)
      ctx.fillStyle = '#ff6b35';
      ctx.beginPath(); ctx.arc(W*0.7, H*0.6, 30, 0, Math.PI*2); ctx.fill();
      drawMemeText(ctx, W, H, top, bottom);
    }

    function drawTwoButtons(ctx, W, H, top, bottom) {
      ctx.fillStyle = '#fff';
      ctx.fillRect(0, 0, W, H);
      // Two buttons
      ctx.fillStyle = '#d0021b';
      ctx.beginPath(); ctx.arc(W/2 - 60, H/2, 30, 0, Math.PI*2); ctx.fill();
      ctx.fillStyle = '#4a90d9';
      ctx.beginPath(); ctx.arc(W/2 + 60, H/2, 30, 0, Math.PI*2); ctx.fill();
      drawMemeText(ctx, W, H, top, bottom);
    }

    function drawChangeMyMind(ctx, W, H, top, bottom) {
      ctx.fillStyle = '#87ceeb';
      ctx.fillRect(0, 0, W, H);
      // Person at table
      ctx.fillStyle = '#8b4513';
      ctx.beginPath(); ctx.arc(W*0.7, H*0.5, 50, 0, Math.PI*2); ctx.fill();
      drawMemeText(ctx, W, H, top, bottom);
    }

    // ===== Initial render if template selected =====
    // (nothing to do on load)

  // Sample image & Next Step
  (function() {
    var _handleFile = typeof handleFile === 'function' ? handleFile : null;
    if (_handleFile) {
      window.initSampleButton('https://images.unsplash.com/photo-1526336024174-e58f5cdd8e13?w=800&q=80', _handleFile);
    }
    // Show next-step on download click
    var dlBtn = document.getElementById('downloadBtn') || document.querySelector('.btn-primary[onclick*="download"], .btn-secondary[onclick*="download"]');
    if (dlBtn) {
      dlBtn.addEventListener('click', function() { SmartImgNextStep.show(); });
    }
  })();

let currentFile = null;
let currentImageDataUrl = null;
let parsedMetadata = null;

const dropzone = document.getElementById('dropzone');
const fileInput = document.getElementById('fileInput');
const resultsSection = document.getElementById('resultsSection');
const previewImg = document.getElementById('previewImg');
const metaSections = document.getElementById('metaSections');
const status = document.getElementById('status');
const resetBtn = document.getElementById('resetBtn');

dropzone.addEventListener('dragover', e => { e.preventDefault(); dropzone.classList.add('drag'); });
dropzone.addEventListener('dragleave', () => { dropzone.classList.remove('drag'); });
dropzone.addEventListener('drop', e => {
  e.preventDefault();
  dropzone.classList.remove('drag');
  if (e.dataTransfer.files[0]) handleFile(e.dataTransfer.files[0]);
});
fileInput.addEventListener('change', e => { if (e.target.files[0]) handleFile(e.target.files[0]); });

function handleFile(file) {
  if (!file || !file.type.startsWith('image/')) {
    alert('Please select an image file.');
    return;
  }
  currentFile = file;
  status.textContent = 'Loading...';
  const reader = new FileReader();
  reader.onload = e => {
    currentImageDataUrl = e.target.result;
    previewImg.src = currentImageDataUrl;
    dropzone.style.display = 'none';
    resultsSection.style.display = 'block';
    status.textContent = 'Loaded: ' + file.name;
  };
  reader.readAsDataURL(file);
}

resetBtn && resetBtn.addEventListener('click', () => {
  currentFile = null;
  currentImageDataUrl = null;
  parsedMetadata = null;
  resultsSection.style.display = 'none';
  dropzone.style.display = '';
  status.textContent = '';
  metaSections.innerHTML = '';
  previewImg.src = '';
  fileInput.value = '';
});

const $ = id => document.getElementById(id);
const fileInput = $('fileInput'), uploadArea = $('uploadArea'), workspace = $('workspace');
const langSelect = $('langSelect'), ocrBtn = $('ocrBtn'), copyBtn = $('copyBtn');
const downloadBtn = $('downloadBtn'), newBtn = $('newBtn');
const previewImg = $('previewImg'), ocrResult = $('ocrResult');
const progressArea = $('progressArea'), statusText = $('statusText'), progressFill = $('progressFill');

let imageDataUrl = null;

uploadArea.addEventListener('click', () => fileInput.click());
uploadArea.addEventListener('dragover', e => { e.preventDefault(); uploadArea.style.borderColor = '#4f46e5'; });
uploadArea.addEventListener('dragleave', () => { uploadArea.style.borderColor = '#d1d5db'; });
uploadArea.addEventListener('drop', e => {
  e.preventDefault(); uploadArea.style.borderColor = '#d1d5db';
  if (e.dataTransfer.files.length) loadImage(e.dataTransfer.files[0]);
});
fileInput.addEventListener('change', () => { if (fileInput.files.length) loadImage(fileInput.files[0]); });

function loadImage(file) {
  const reader = new FileReader();
  reader.onload = e => {
    imageDataUrl = e.target.result;
    previewImg.src = imageDataUrl;
    uploadArea.style.display = 'none';
    workspace.style.display = 'block';
    ocrResult.value = '';
  };
  reader.readAsDataURL(file);
}

ocrBtn.addEventListener('click', async () => {
  if (!imageDataUrl) return;
  ocrBtn.disabled = true;
  progressArea.style.display = 'block';
  statusText.textContent = 'Loading OCR engine (first run may take a moment)...';
  progressFill.style.width = '10%';

  try {
    statusText.textContent = 'Recognizing text...';
    progressFill.style.width = '50%';

    const result = await Tesseract.recognize(imageDataUrl, langSelect.value, {
      logger: m => {
        if (m.status === 'recognizing text') {
          progressFill.style.width = (50 + m.progress * 40) + '%';
        }
      }
    });

    ocrResult.value = result.data.text;
    statusText.textContent = `Done! Confidence: ${Math.round(result.data.confidence)}%`;
    progressFill.style.width = '100%';
  } catch (err) {
    statusText.textContent = 'Error: ' + err.message;
    ocrResult.value = 'OCR failed: ' + err.message;
  } finally {
    ocrBtn.disabled = false;
    setTimeout(() => { progressArea.style.display = 'none'; progressFill.style.width = '0%'; }, 2000);
  }
});

copyBtn.addEventListener('click', () => {
  navigator.clipboard.writeText(ocrResult.value).then(() => {
    copyBtn.textContent = 'Copied!';
    setTimeout(() => { copyBtn.textContent = 'Copy Text'; }, 1500);
  });
});

downloadBtn.addEventListener('click', () => {
  const blob = new Blob([ocrResult.value], { type: 'text/plain' });
  const a = document.createElement('a');
  a.download = 'extracted-text.txt';
  a.href = URL.createObjectURL(blob);
  a.click();
  URL.revokeObjectURL(a.href);
});

newBtn.addEventListener('click', () => {
  workspace.style.display = 'none';
  uploadArea.style.display = 'block';
  fileInput.value = '';
  ocrResult.value = '';
  imageDataUrl = null;
});

tools.inline_style:
.tool-workspace { display: flex; flex-direction: column; gap: 24px; }
    .controls { background: var(--bg-primary); border: 1px solid var(--border); border-radius: 12px; padding: 24px; margin-bottom: 24px; }
    .controls h2 { font-size: 1.2rem; color: var(--text-primary); margin-bottom: 1rem; padding-bottom: 0.5rem; border-bottom: 2px solid var(--accent); }
    .control-row { display: flex; align-items: center; gap: 16px; margin-bottom: 16px; flex-wrap: wrap; }
    .control-row label { font-weight: 600; min-width: 120px; color: var(--text-secondary); font-size: 0.85rem; }
    .control-row select, .control-row input[type="number"] { padding: 8px 12px; border: 1px solid var(--border); border-radius: 6px; background: var(--bg-primary); color: var(--text-primary); font-size: 0.85rem; }
    .btn-row { display: flex; gap: 12px; flex-wrap: wrap; margin-top: 16px; }
    .pdf-info { background: var(--bg-secondary); border-radius: 8px; padding: 12px 16px; margin-bottom: 16px; font-size: 0.9rem; color: var(--text-primary); }
    .pdf-info strong { color: var(--accent); }
    .pages-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 16px; margin-top: 16px; }
    .page-item { border: 2px solid var(--border); border-radius: 8px; overflow: hidden; background: var(--bg-primary); text-align: center; }
    .page-item canvas { width: 100%; display: block; }
    .page-num { padding: 8px 12px; font-weight: 600; color: var(--text-secondary); font-size: 0.85rem; border-top: 1px solid var(--border); }
    .dl-btn { display: block; width: 100%; padding: 8px; background: var(--accent); color: white; border: none; cursor: pointer; font-size: 0.85rem; font-weight: 600; transition: all 0.2s; }
    .dl-btn:hover { background: var(--accent-hover); }
    .status-text { text-align: center; color: var(--text-secondary); font-size: 0.9rem; margin: 16px 0; }
    .preview-section { background: var(--bg-primary); border: 1px solid var(--border); border-radius: 12px; padding: 24px; margin-bottom: 24px; }
    .preview-section h2 { font-size: 1.2rem; color: var(--text-primary); margin-bottom: 1rem; padding-bottom: 0.5rem; border-bottom: 2px solid var(--accent); }
    .info-box { background: rgba(99,102,241,0.1); border-left: 4px solid var(--accent); padding: 16px 20px; border-radius: 8px; margin-bottom: 24px; }
    .info-box h3 { color: var(--accent); margin-bottom: 8px; font-size: 1rem; }
    .info-box p, .info-box li { color: var(--text-secondary); font-size: 0.9rem; }
