(function() {
        const dropzone = document.getElementById('dropzone');
        const fileInput = document.getElementById('fileInput');
        const chooseFileBtn = document.getElementById('chooseFileBtn');
        const controlsSection = document.getElementById('controlsSection');
        const pdfInfo = document.getElementById('pdfInfo');
        const outputFormat = document.getElementById('outputFormat');
        const scaleFactor = document.getElementById('scaleFactor');
        const pageFrom = document.getElementById('pageFrom');
        const pageTo = document.getElementById('pageTo');
        const convertBtn = document.getElementById('convertBtn');
        const resetBtn = document.getElementById('resetBtn');
        const statusSection = document.getElementById('statusSection');
        const statusText = document.getElementById('statusText');
        const resultSection = document.getElementById('resultSection');
        const pagesGrid = document.getElementById('pagesGrid');
        const convertedCount = document.getElementById('convertedCount');
        const downloadAllBtn = document.getElementById('downloadAllBtn');

        let pdfDoc = null;
        let convertedPages = []; // { pageNum, dataUrl, blob }

        // Lazy-init pdf.js worker only when pdfjsLib is actually available
        function ensurePdfJsWorker() {
            if (typeof pdfjsLib !== 'undefined' && pdfjsLib.GlobalWorkerOptions) {
                pdfjsLib.GlobalWorkerOptions.workerSrc = '/js/pdf.worker.min.js?v=3.11.174';
                return true;
            }
            return false;
        }

        // Upload — single-trigger: dropzone click + button click + drag/drop
        if (dropzone) {
            // Click on empty area of dropzone → open file dialog
            dropzone.addEventListener('click', function(e) {
                if (e.target === chooseFileBtn || (chooseFileBtn && chooseFileBtn.contains(e.target))) {
                    return; // button has its own handler
                }
                fileInput.click();
            });
            dropzone.addEventListener('dragover', function(e) { e.preventDefault(); e.stopPropagation(); dropzone.classList.add('dragover'); });
            dropzone.addEventListener('dragleave', function(e) { e.preventDefault(); dropzone.classList.remove('dragover'); });
            dropzone.addEventListener('drop', function(e) {
                e.preventDefault(); e.stopPropagation();
                dropzone.classList.remove('dragover');
                if (e.dataTransfer.files.length > 0) handleFile(e.dataTransfer.files[0]);
            });
        }
        if (chooseFileBtn) {
            chooseFileBtn.addEventListener('click', function(e) {
                e.preventDefault();
                e.stopPropagation();
                fileInput.click();
            });
        }
        if (fileInput) {
            fileInput.addEventListener('change', function(e) {
                if (e.target.files.length > 0) handleFile(e.target.files[0]);
            });
        }

        function handleFile(file) {
            if (file.type !== 'application/pdf' && !file.name.endsWith('.pdf')) {
                alert('Please upload a PDF file.');
                return;
            }

            var baPreview = document.getElementById('beforeAfterPreview');
            if (baPreview) baPreview.classList.add('hidden');

            const reader = new FileReader();
            reader.onload = function(e) {
                loadPDF(e.target.result);
            };
            reader.readAsArrayBuffer(file);

            // Show controls
            pdfInfo.innerHTML = `<strong>File:</strong> ${file.name} &nbsp;|&nbsp; <strong>Size:</strong> ${(file.size/1024/1024).toFixed(2)} MB`;
            pageFrom.placeholder = '1';
            pageTo.placeholder = '?';
            controlsSection.classList.remove('hidden');
            resultSection.classList.add('hidden');
            convertedPages = [];
        }

        async function loadPDF(arrayBuffer) {
            if (!ensurePdfJsWorker()) {
                alert('PDF library failed to load. Please check your network connection and refresh the page.');
                return;
            }
            try {
                const loadingTask = pdfjsLib.getDocument({ data: arrayBuffer });
                pdfDoc = await loadingTask.promise;
                pageTo.placeholder = pdfDoc.numPages;
                pdfInfo.innerHTML += ` &nbsp;|&nbsp; <strong>Pages:</strong> ${pdfDoc.numPages}`;
                statusSection.classList.add('hidden');
            } catch (err) {
                alert('Failed to load PDF: ' + err.message);
            }
        }

        // Convert
        convertBtn.addEventListener('click', async function() {
            if (!pdfDoc) {
                alert('Please upload a PDF first.');
                return;
            }

            const format = outputFormat.value;
            const scale = parseFloat(scaleFactor.value);
            const from = pageFrom.value ? parseInt(pageFrom.value) : 1;
            const to = pageTo.value ? parseInt(pageTo.value) : pdfDoc.numPages;

            if (from < 1 || to > pdfDoc.numPages || from > to) {
                alert(`Please enter a valid page range (1-${pdfDoc.numPages}).`);
                return;
            }

            statusSection.classList.remove('hidden');
            resultSection.classList.add('hidden');
            convertBtn.disabled = true;
            convertedPages = [];
            pagesGrid.innerHTML = '';

            const totalPages = to - from + 1;

            for (let i = from; i <= to; i++) {
                statusText.textContent = `Converting page ${i}/${to}...`;

                try {
                    const page = await pdfDoc.getPage(i);
                    const viewport = page.getViewport({ scale: scale });

                    const canvas = document.createElement('canvas');
                    canvas.width = viewport.width;
                    canvas.height = viewport.height;
                    const ctx = canvas.getContext('2d');

                    await page.render({
                        canvasContext: ctx,
                        viewport: viewport
                    }).promise;

                    const mimeType = format === 'jpeg' ? 'image/jpeg' : (format === 'webp' ? 'image/webp' : 'image/png');
                    const quality = format === 'jpeg' ? 0.92 : (format === 'webp' ? 0.92 : undefined);
                    const dataUrl = canvas.toDataURL(mimeType, quality);

                    convertedPages.push({ pageNum: i, dataUrl, canvas });

                    // Add to grid
                    const item = document.createElement('div');
                    item.className = 'page-item';
                    const previewCanvas = document.createElement('canvas');
                    // Create a smaller preview
                    const previewScale = Math.min(180 / canvas.width, 1);
                    previewCanvas.width = canvas.width * previewScale;
                    previewCanvas.height = canvas.height * previewScale;
                    previewCanvas.getContext('2d').drawImage(canvas, 0, 0, previewCanvas.width, previewCanvas.height);
                    item.appendChild(previewCanvas);

                    const numDiv = document.createElement('div');
                    numDiv.className = 'page-num';
                    numDiv.textContent = `Page ${i}`;
                    item.appendChild(numDiv);

                    const dlBtn = document.createElement('button');
                    dlBtn.className = 'dl-btn';
                    dlBtn.textContent = 'Download';
                    dlBtn.onclick = function() {
                        const a = document.createElement('a');
                        a.href = dataUrl;
                        a.download = `page-${i}.${format === 'jpeg' ? 'jpg' : format}`;
                        a.click();
                    };
                    item.appendChild(dlBtn);

                    pagesGrid.appendChild(item);
                    convertedCount.textContent = convertedPages.length;

                } catch (err) {
                    console.error(`Error converting page ${i}:`, err);
                }
            }

            statusText.textContent = `Done! Converted ${convertedPages.length} page(s).`;
            resultSection.classList.remove('hidden');
            convertBtn.disabled = false;
        });

        // Download all as ZIP
        downloadAllBtn.addEventListener('click', async function() {
            if (convertedPages.length === 0) return;

            statusText.textContent = 'Creating ZIP file...';
            statusSection.classList.remove('hidden');

            // Use dynamic import for JSZip (we'll load it from CDN)
            const JSZip = window.JSZip;
            if (!JSZip) {
                // Load JSZip from CDN
                const script = document.createElement('script');
                script.src = 'https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js';
                script.onload = function() {
                    createZip(window.JSZip);
                };
                document.head.appendChild(script);
            } else {
                createZip(JSZip);
            }
        });

        function createZip(JSZip) {
            const zip = new JSZip();
            const format = outputFormat.value;
            const ext = format === 'jpeg' ? 'jpg' : format;

            convertedPages.forEach(page => {
                const base64 = page.dataUrl.split(',')[1];
                zip.file(`page-${page.pageNum}.${ext}`, base64, { base64: true });
            });

            zip.generateAsync({ type: 'blob' }).then(function(blob) {
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = 'pdf-pages.zip';
                a.click();
                URL.revokeObjectURL(url);
                statusSection.classList.add('hidden');
            });
        }

        // Reset
        resetBtn.addEventListener('click', function() {
            pdfDoc = null;
            convertedPages = [];
            pagesGrid.innerHTML = '';
            controlsSection.classList.add('hidden');
            resultSection.classList.add('hidden');
            statusSection.classList.add('hidden');
            fileInput.value = '';
            var baPreview = document.getElementById('beforeAfterPreview');
            if (baPreview) baPreview.classList.remove('hidden');
        });
    })();

// === State ===
let origImage = null;
let origImageData = null;
let canvas = document.getElementById('previewCanvas');
let ctx = canvas.getContext('2d');
let beforeCanvas, afterCanvas;
let isComparing = false;

// === File Handling ===
const dropzone = document.getElementById('dropzone');
const fileInput = document.getElementById('fileInput');
dropzone.addEventListener('dragover', e => { e.preventDefault(); dropzone.classList.add('drag'); });
dropzone.addEventListener('dragleave', () => dropzone.classList.remove('drag'));
dropzone.addEventListener('drop', e => {
  e.preventDefault(); dropzone.classList.remove('drag');
  if (e.dataTransfer.files[0]) handleFile(e.dataTransfer.files[0]);
});
fileInput.addEventListener('change', e => { if (e.target.files[0]) handleFile(e.target.files[0]); });

function handleFile(file) {
  if (!file.type.startsWith('image/')) { alert('Please select an image file.'); return; }
  const reader = new FileReader();
  reader.onload = e => {
    const img = new Image();
    img.onload = () => {
      origImage = img;
      canvas.width = img.width; canvas.height = img.height;
      ctx.drawImage(img, 0, 0);
      origImageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      canvas.style.display = 'block';
      document.getElementById('placeholderText').style.display = 'none';
      document.getElementById('downloadBtn').disabled = false;
      resetSliders();
    };
    img.src = e.target.result;
  };
  reader.readAsDataURL(file);
}

// === Pixel Data Helpers ===
function getPixelData(imageData) {
  return {
    data: new Uint8ClampedArray(imageData.data),
    width: imageData.width,
    height: imageData.height
  };
}

function putPixelData(pixels) {
  const id = ctx.createImageData(pixels.width, pixels.height);
  id.data.set(pixels.data);
  return id;
}

// === Denoise: Median Filter (3x3) ===
function medianFilter(pixels, radius) {
  const { data, width, height } = pixels;
  const out = new Uint8ClampedArray(data);
  const r = Math.max(1, Math.round(radius));
  const size = r * 2 + 1;
  const total = size * size;

  for (let y = r; y < height - r; y++) {
    for (let x = r; x < width - r; x++) {
      const ri = [], gi = [], bi = [];
      for (let dy = -r; dy <= r; dy++) {
        for (let dx = -r; dx <= r; dx++) {
          const idx = ((y + dy) * width + (x + dx)) * 4;
          ri.push(data[idx]);
          gi.push(data[idx + 1]);
          bi.push(data[idx + 2]);
        }
      }
      ri.sort((a,b)=>a-b); gi.sort((a,b)=>a-b); bi.sort((a,b)=>a-b);
      const mid = Math.floor(total / 2);
      const idx = (y * width + x) * 4;
      out[idx] = ri[mid];
      out[idx + 1] = gi[mid];
      out[idx + 2] = bi[mid];
    }
  }
  return out;
}

// === Scratch Removal: adaptive neighbor averaging ===
function removeScratches(pixels, strength) {
  const { data, width, height } = pixels;
  const out = new Uint8ClampedArray(data);
  const threshold = Math.max(10, Math.round(60 - strength * 0.5));

  for (let y = 1; y < height - 1; y++) {
    for (let x = 1; x < width - 1; x++) {
      const idx = (y * width + x) * 4;
      let isScratch = false;
      const leftIdx = idx - 4;
      const rightIdx = idx + 4;
      for (let c = 0; c < 3; c++) {
        const center = data[idx + c];
        const left = data[leftIdx + c];
        const right = data[rightIdx + c];
        const diffL = Math.abs(center - left);
        const diffR = Math.abs(center - right);
        if (diffL > threshold && diffR > threshold && Math.abs(left - right) < threshold * 0.6) {
          isScratch = true;
          break;
        }
      }
      if (isScratch) {
        const topIdx = ((y - 1) * width + x) * 4;
        const bottomIdx = ((y + 1) * width + x) * 4;
        for (let c = 0; c < 3; c++) {
          out[idx + c] = (data[leftIdx + c] + data[rightIdx + c] + data[topIdx + c] + data[bottomIdx + c]) >> 2;
        }
      }
    }
  }
  return out;
}

// === Contrast: Histogram Stretching ===
function histogramStretch(pixels, strength) {
  const { data, width, height } = pixels;
  const out = new Uint8ClampedArray(data);
  const factor = strength / 100;
  if (factor <= 0) return out;

  let minR = 255, maxR = 0, minG = 255, maxG = 0, minB = 255, maxB = 0;
  for (let i = 0; i < data.length; i += 4) {
    if (data[i] < minR) minR = data[i];
    if (data[i] > maxR) maxR = data[i];
    if (data[i+1] < minG) minG = data[i+1];
    if (data[i+1] > maxG) maxG = data[i+1];
    if (data[i+2] < minB) minB = data[i+2];
    if (data[i+2] > maxB) maxB = data[i+2];
  }

  const rangeR = maxR - minR || 1;
  const rangeG = maxG - minG || 1;
  const rangeB = maxB - minB || 1;

  const amount = Math.min(1, factor * 1.2);
  for (let i = 0; i < data.length; i += 4) {
    const r = ((data[i] - minR) / rangeR) * 255;
    const g = ((data[i+1] - minG) / rangeG) * 255;
    const b = ((data[i+2] - minB) / rangeB) * 255;
    out[i] = Math.round(data[i] + (r - data[i]) * amount);
    out[i+1] = Math.round(data[i+1] + (g - data[i+1]) * amount);
    out[i+2] = Math.round(data[i+2] + (b - data[i+2]) * amount);
  }
  return out;
}

// === Sharpen: Unsharp Mask ===
function unsharpMask(pixels, strength) {
  const { data, width, height } = pixels;
  const out = new Uint8ClampedArray(data);
  const amount = (strength / 100) * 0.6;
  if (amount <= 0) return out;

  const kernel = [1, 2, 1, 2, 4, 2, 1, 2, 1];
  const kSum = 16;

  for (let y = 1; y < height - 1; y++) {
    for (let x = 1; x < width - 1; x++) {
      for (let c = 0; c < 3; c++) {
        let blurred = 0;
        let ki = 0;
        for (let dy = -1; dy <= 1; dy++) {
          for (let dx = -1; dx <= 1; dx++) {
            blurred += data[((y+dy)*width + (x+dx))*4 + c] * kernel[ki];
            ki++;
          }
        }
        blurred /= kSum;
        const original = data[(y*width + x)*4 + c];
        const sharpened = original + (original - blurred) * amount;
        out[(y*width + x)*4 + c] = Math.max(0, Math.min(255, Math.round(sharpened)));
      }
    }
  }
  return out;
}

// === Sepia / Warmth ===
function applySepia(pixels, strength) {
  const { data, width, height } = pixels;
  const out = new Uint8ClampedArray(data);
  const amount = Math.min(1, strength / 100);
  if (amount <= 0) return out;

  for (let i = 0; i < data.length; i += 4) {
    const r = data[i], g = data[i+1], b = data[i+2];
    const tr = 0.393 * r + 0.769 * g + 0.189 * b;
    const tg = 0.349 * r + 0.686 * g + 0.168 * b;
    const tb = 0.272 * r + 0.534 * g + 0.131 * b;
    out[i] = Math.round(r + (Math.min(255, tr) - r) * amount);
    out[i+1] = Math.round(g + (Math.min(255, tg) - g) * amount);
    out[i+2] = Math.round(b + (Math.min(255, tb) - b) * amount);
  }
  return out;
}

// === Brightness ===
function adjustBrightness(pixels, value) {
  const { data, width, height } = pixels;
  const out = new Uint8ClampedArray(data);
  const amount = value;
  if (amount === 0) return out;

  for (let i = 0; i < data.length; i += 4) {
    out[i] = Math.max(0, Math.min(255, data[i] + amount * 1.27));
    out[i+1] = Math.max(0, Math.min(255, data[i+1] + amount * 1.27));
    out[i+2] = Math.max(0, Math.min(255, data[i+2] + amount * 1.27));
  }
  return out;
}

// === Main Processing Pipeline ===
function processImage() {
  if (!origImage || !origImageData) return;

  const progressBar = document.getElementById('progressBar');
  const progressFill = document.getElementById('progressFill');
  progressBar.style.display = 'block';

  let pixels = getPixelData(origImageData);

  const denoiseVal = parseInt(document.getElementById('denoiseSlider').value);
  if (denoiseVal > 0) {
    progressFill.style.width = '15%';
    const radius = Math.max(1, Math.round(denoiseVal / 25));
    pixels.data = medianFilter(pixels, radius);
  }

  const scratchVal = parseInt(document.getElementById('scratchSlider').value);
  if (scratchVal > 0) {
    progressFill.style.width = '35%';
    pixels.data = removeScratches(pixels, scratchVal);
  }

  const contrastVal = parseInt(document.getElementById('contrastSlider').value);
  if (contrastVal > 0) {
    progressFill.style.width = '50%';
    pixels.data = histogramStretch(pixels, contrastVal);
  }

  const sharpenVal = parseInt(document.getElementById('sharpenSlider').value);
  if (sharpenVal > 0) {
    progressFill.style.width = '65%';
    pixels.data = unsharpMask(pixels, sharpenVal);
  }

  const brightVal = parseInt(document.getElementById('brightSlider').value);
  if (brightVal !== 0) {
    progressFill.style.width = '80%';
    pixels.data = adjustBrightness(pixels, brightVal);
  }

  const sepiaVal = parseInt(document.getElementById('sepiaSlider').value);
  if (sepiaVal > 0) {
    progressFill.style.width = '90%';
    pixels.data = applySepia(pixels, sepiaVal);
  }

  ctx.putImageData(putPixelData(pixels), 0, 0);
  progressFill.style.width = '100%';

  setTimeout(() => {
    progressBar.style.display = 'none';
    progressFill.style.width = '0%';
  }, 500);
}

// === Slider Events ===
function onSliderChange() {
  document.getElementById('denoiseVal').textContent = document.getElementById('denoiseSlider').value;
  document.getElementById('scratchVal').textContent = document.getElementById('scratchSlider').value;
  document.getElementById('contrastVal').textContent = document.getElementById('contrastSlider').value;
  document.getElementById('sharpenVal').textContent = document.getElementById('sharpenSlider').value;
  document.getElementById('brightVal').textContent = document.getElementById('brightSlider').value;
  document.getElementById('sepiaVal').textContent = document.getElementById('sepiaSlider').value;
  processImage();
  if (isComparing) updateCompare();
}

function resetSliders() {
  ['denoise','scratch','contrast','sharpen','bright','sepia'].forEach(id => {
    const slider = document.getElementById(id + 'Slider');
    const val = document.getElementById(id + 'Val');
    if (slider) slider.value = 0;
    if (val) val.textContent = '0';
  });
  if (origImage) {
    ctx.drawImage(origImage, 0, 0);
    origImageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
  }
  if (isComparing) updateCompare();
}

// === Presets ===
function applyPreset(name) {
  const presets = {
    'auto-restore':     { denoise:45, scratch:55, contrast:50, sharpen:40, bright:10, sepia:0 },
    'remove-scratches': { denoise:20, scratch:80, contrast:20, sharpen:20, bright:5, sepia:0 },
    'reduce-noise':     { denoise:70, scratch:10, contrast:15, sharpen:25, bright:0, sepia:0 },
    'sharpen-face':    { denoise:15, scratch:10, contrast:25, sharpen:70, bright:10, sepia:0 },
    'enhance-contrast': { denoise:10, scratch:10, contrast:75, sharpen:30, bright:0, sepia:0 }
  };
  const p = presets[name];
  if (!p) return;

  document.querySelectorAll('.preset-btn').forEach(b => b.classList.remove('active'));
  const activeBtn = document.querySelector(`.preset-btn[onclick*="${name}"]`);
  if (activeBtn) activeBtn.classList.add('active');

  const map = { denoise:'denoise', scratch:'scratch', contrast:'contrast', sharpen:'sharpen', bright:'bright', sepia:'sepia' };
  Object.keys(p).forEach(key => {
    const slider = document.getElementById(map[key] + 'Slider');
    if (slider) slider.value = p[key];
  });
  onSliderChange();
}

// === Compare (Before/After Slider) ===
function toggleCompare() {
  isComparing = document.getElementById('compareToggle').checked;
  document.getElementById('compareBox').style.display = isComparing ? 'block' : 'none';
  if (isComparing) setupCompare();
}

function setupCompare() {
  beforeCanvas = document.getElementById('beforeCanvas');
  afterCanvas = document.getElementById('afterCanvas');
  if (!origImage) return;
  const maxW = 800, maxH = 600;
  let w = origImage.width, h = origImage.height;
  if (w > maxW) { h = h * maxW / w; w = maxW; }
  if (h > maxH) { w = w * maxH / h; h = maxH; }
  beforeCanvas.width = afterCanvas.width = w;
  beforeCanvas.height = afterCanvas.height = h;
  const bCtx = beforeCanvas.getContext('2d');
  bCtx.drawImage(origImage, 0, 0, w, h);
  updateCompare();

  const box = document.getElementById('compareBox');
  let dragging = false;
  const moveFn = e => {
    if (!dragging) return;
    const rect = box.getBoundingClientRect();
    let x = e.clientX - rect.left;
    x = Math.max(0, Math.min(rect.width, x));
    afterCanvas.style.clipPath = 'inset(0 ' + (rect.width - x) + 'px 0 0)';
    document.getElementById('sliderHandle').style.left = x + 'px';
  };
  box.addEventListener('mousedown', e => { dragging = true; moveFn(e); });
  document.addEventListener('mousemove', moveFn);
  document.addEventListener('mouseup', () => { dragging = false; });
  box.addEventListener('touchstart', e => { dragging = true; const t = e.touches[0]; moveFn({clientX: t.clientX}); });
  document.addEventListener('touchmove', e => { if (dragging) { const t = e.touches[0]; moveFn({clientX: t.clientX}); }});
  document.addEventListener('touchend', () => { dragging = false; });
  setTimeout(() => {
    const rect = box.getBoundingClientRect();
    const mid = Math.round(rect.width / 2);
    afterCanvas.style.clipPath = 'inset(0 ' + (rect.width - mid) + 'px 0 0)';
    document.getElementById('sliderHandle').style.left = mid + 'px';
  }, 50);
}

function updateCompare() {
  if (!afterCanvas || !origImage) return;
  const aCtx = afterCanvas.getContext('2d');
  aCtx.drawImage(canvas, 0, 0, afterCanvas.width, afterCanvas.height);
}

function downloadImage() {
  const link = document.createElement('a');
  link.download = 'restored-photo.png';
  link.href = canvas.toDataURL('image/png');
  link.click();
}

// ===== Paper size presets (width × height in inches) =====
    const PAPER = {
      a4:         { w: 8.2677,  h: 11.6929, label: 'A4 (210×297mm)' },
      letter:     { w: 8.5,     h: 11,      label: 'Letter (8.5×11")' },
      a5:         { w: 5.8268,  h: 8.2677,  label: 'A5 (148×210mm)' },
      '4x6':      { w: 4,       h: 6,       label: '4×6" (10×15cm)' },
      '5x7':      { w: 5,       h: 7,       label: '5×7" (13×18cm)' },
      business:   { w: 3.5,     h: 2,       label: 'Business Card (3.5×2")' },
      custom:     null,
    };

    // ===== State =====
    let originalImg = null;
    let activePreset = null;

    // ===== DOM =====
    const dropzone = document.getElementById('dropzone');
    const fileInput = document.getElementById('fileInput');
    const workspace = document.getElementById('workspace');
    const canvas = document.getElementById('previewCanvas');
    const ctx = canvas.getContext('2d');
    const presetGrid = document.getElementById('presetGrid');
    const customSizeDiv = document.getElementById('customSize');
    const dpiSelect = document.getElementById('dpiSelect');
    const outputFormat = document.getElementById('outputFormat');
    const dimensionInfo = document.getElementById('dimensionInfo');

    // ===== Init Preset Buttons =====
    presetGrid.querySelectorAll('.preset-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        document.querySelectorAll('.preset-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        activePreset = btn.dataset.preset;
        customSizeDiv.style.display = activePreset === 'custom' ? '' : 'none';
        if (originalImg) renderPreview();
      });
    });

    // ===== File Upload =====
    setupDropzone({
      dropzoneId: 'dropzone',
      inputId: 'fileInput',
      onFile: async (file) => {
        try {
          originalImg = await ImageUtils.load(file);
          dropzone.style.display = 'none';
          workspace.style.display = 'block';
          // Auto-select A4
          if (!activePreset) {
            document.querySelector('[data-preset="a4"]').click();
          } else {
            renderPreview();
          }
        } catch (e) {
          ImageUtils.showToast('Failed to load image', 'error');
        }
      }
    });

    // ===== DPI / Format change =====
    dpiSelect.addEventListener('change', () => { if (originalImg) renderPreview(); });
    outputFormat.addEventListener('change', () => { if (originalImg) renderPreview(); });
    document.getElementById('customW').addEventListener('input', () => { if (activePreset === 'custom' && originalImg) renderPreview(); });
    document.getElementById('customH').addEventListener('input', () => { if (activePreset === 'custom' && originalImg) renderPreview(); });

    // ===== Reset =====
    document.getElementById('resetBtn').addEventListener('click', () => {
      originalImg = null;
      workspace.style.display = 'none';
      dropzone.style.display = '';
      fileInput.value = '';
      document.querySelectorAll('.preset-btn').forEach(b => b.classList.remove('active'));
      activePreset = null;
      customSizeDiv.style.display = 'none';
      dimensionInfo.style.display = 'none';
    });

    // ===== Download =====
    document.getElementById('downloadBtn').addEventListener('click', () => {
      const mime = outputFormat.value;
      const ext = mime === 'image/jpeg' ? 'jpg' : 'png';
      const preset = PAPER[activePreset];
      const label = preset ? preset.label.replace(/[^a-zA-Z0-9]/g, '_') : 'custom';
      ImageUtils.download(canvas, 'print-ready_' + label + '.' + ext, mime);
      ImageUtils.showToast('Image downloaded!');
    });

    // ===== Render =====
    function renderPreview() {
      if (!originalImg || !activePreset) return;

      const dpi = parseInt(dpiSelect.value);
      let pw, ph; // paper width/height in inches

      if (activePreset === 'custom') {
        pw = parseFloat(document.getElementById('customW').value) || 8.5;
        ph = parseFloat(document.getElementById('customH').value) || 11;
      } else {
        const p = PAPER[activePreset];
        if (!p) return;
        pw = p.w; ph = p.h;
      }

      const canvasW = Math.round(pw * dpi);
      const canvasH = Math.round(ph * dpi);

      canvas.width = canvasW;
      canvas.height = canvasH;

      // White background (print-ready)
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, canvasW, canvasH);

      // Fit original image into canvas (contain, center)
      const imgW = originalImg.width;
      const imgH = originalImg.height;
      const ratio = Math.min(canvasW / imgW, canvasH / imgH);
      const drawW = Math.round(imgW * ratio);
      const drawH = Math.round(imgH * ratio);
      const offX = Math.round((canvasW - drawW) / 2);
      const offY = Math.round((canvasH - drawH) / 2);

      ctx.drawImage(originalImg, offX, offY, drawW, drawH);

      // Update info
      dimensionInfo.style.display = 'flex';
      document.getElementById('outDims').textContent = canvasW + ' × ' + canvasH + ' px';
      document.getElementById('printSize').textContent = pw.toFixed(2) + '" × ' + ph.toFixed(2) + '" @ ' + dpi + ' DPI';

      // Estimate file size
      const mime = outputFormat.value;
      const estBytes = mime === 'image/jpeg'
        ? Math.round(canvasW * canvasH * 0.15)
        : Math.round(canvasW * canvasH * 3);
      document.getElementById('estSize').textContent = ImageUtils.formatBytes(estBytes);
    }

  // Sample image & Next Step
  (function() {
    var _handleFile = typeof handleFile === 'function' ? handleFile : null;
    if (_handleFile) {
      window.initSampleButton('https://images.unsplash.com/photo-1513364776144-60967b0f800f?w=800&q=80', _handleFile);
    }
    // Show next-step on download click
    var dlBtn = document.getElementById('downloadBtn') || document.querySelector('.btn-primary[onclick*="download"], .btn-secondary[onclick*="download"]');
    if (dlBtn) {
      dlBtn.addEventListener('click', function() { SmartImgNextStep.show(); });
    }
  })();

let files = [];
let model = null;
let processing = false;
let selectedBg = '#ffffff';

const fileInput = document.getElementById('fileInput');
const dropzone = document.getElementById('dropzone');
const workspace = document.getElementById('workspace');
const productGrid = document.getElementById('productGrid');
const processBtn = document.getElementById('processBtn');
const downloadAllBtn = document.getElementById('downloadAllBtn');
const addMoreBtn = document.getElementById('addMoreBtn');
const clearBtn = document.getElementById('clearBtn');
const progBar = document.getElementById('progBar');
const progFill = document.getElementById('progFill');
const status = document.getElementById('status');
const beforeAfter = document.getElementById('beforeAfterPreview');
const bgBtns = document.querySelectorAll('.bg-btn');

// Background selector
bgBtns.forEach(function(btn) {
  btn.addEventListener('click', function() {
    bgBtns.forEach(function(b) { b.classList.remove('active'); });
    btn.classList.add('active');
    selectedBg = btn.getAttribute('data-bg');
    // Update after image bg style
    document.querySelectorAll('.product-card-img.after').forEach(function(img) {
      var val = selectedBg;
      if (val === '#ffffff') { img.className = 'product-card-img after bg-preview-white'; }
      else if (val === 'transparent') { img.className = 'product-card-img after bg-preview-transparent'; }
      else if (val === '#e8f4f8') { img.className = 'product-card-img after bg-preview-blue'; }
      else if (val === '#f0f0f0') { img.className = 'product-card-img after bg-preview-gray'; }
    });
  });
});

fileInput.addEventListener('change', function() {
  var arr = Array.from(fileInput.files).filter(function(f) { return f.type && f.type.startsWith('image/'); });
  if (arr.length) addFiles(arr);
  fileInput.value = '';
});

dropzone.addEventListener('dragover', function(e) { e.preventDefault(); dropzone.classList.add('drag'); });
dropzone.addEventListener('dragleave', function() { dropzone.classList.remove('drag'); });
dropzone.addEventListener('drop', function(e) {
  e.preventDefault();
  dropzone.classList.remove('drag');
  var arr = Array.from(e.dataTransfer.files).filter(function(f) { return f.type && f.type.startsWith('image/'); });
  if (arr.length) addFiles(arr);
});

function addFiles(arr) {
  arr.forEach(function(f) {
    files.push({ name: f.name, file: f, url: URL.createObjectURL(f), resultBlob: null, resultUrl: null, error: null });
  });
  dropzone.style.display = 'none';
  workspace.style.display = 'block';
  if (beforeAfter) beforeAfter.classList.add('hidden');
  renderGrid();
}

function formatSize(bytes) {
  if (bytes < 1024) return bytes + ' B';
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
  return (bytes / (1024 * 1024)).toFixed(2) + ' MB';
}

function getBgClass(val) {
  if (val === '#ffffff') return 'bg-preview-white';
  if (val === 'transparent') return 'bg-preview-transparent';
  if (val === '#e8f4f8') return 'bg-preview-blue';
  if (val === '#f0f0f0') return 'bg-preview-gray';
  return 'bg-preview-white';
}

function renderGrid() {
  productGrid.innerHTML = '';
  files.forEach(function(item, i) {
    var card = document.createElement('div');
    card.className = 'product-card';

    var badgeClass = 'badge-pending';
    var badgeText = '⏳ Pending';
    if (item.error) { badgeClass = 'badge-error'; badgeText = '❌ Error'; }
    else if (processing && !item.resultBlob && !item.error) { badgeClass = 'badge-processing'; badgeText = '⏳ Processing...'; }
    else if (item.resultBlob) { badgeClass = 'badge-done'; badgeText = '✅ Done'; }

    var outName = (item.name || 'product').replace(/\.[^.]+$/, '') + '-white-bg.png';
    var origSize = formatSize(item.file.size);
    var resultSize = item.resultBlob ? formatSize(item.resultBlob.size) : '—';

    var bgClass = getBgClass(selectedBg);
    var afterImg = '';
    if (item.resultBlob && item.resultUrl) {
      afterImg = '<img class="product-card-img after ' + bgClass + '" src="' + item.resultUrl + '" alt="' + item.name + ' with ' + selectedBg + ' background">';
    } else {
      afterImg = '<div class="product-card-img after ' + bgClass + '" style="display:flex;align-items:center;justify-content:center;color:var(--text-muted);font-size:0.85rem;">' + (item.error ? '⚠️ Error' : '⏳') + '</div>';
    }

    var downloadBtn = '<button class="btn-sm" disabled>⬇️ Download</button>';
    if (item.resultBlob && item.resultUrl) {
      downloadBtn = '<a href="' + item.resultUrl + '" download="' + outName + '" class="btn-sm">⬇️ Download</a>';
    }

    card.innerHTML =
      '<div class="product-card-header">' +
        '<span class="product-card-name" title="' + item.name + '">' + item.name + '</span>' +
        '<span class="product-card-badge ' + badgeClass + '">' + badgeText + '</span>' +
        '<button class="product-card-remove" title="Remove" data-index="' + i + '">✕</button>' +
      '</div>' +
      '<div class="product-card-images">' +
        '<img class="product-card-img before" src="' + item.url + '" alt="Original ' + item.name + '">' +
        '<span class="product-card-arrow">→</span>' +
        afterImg +
      '</div>' +
      '<div class="product-card-footer">' +
        '<span class="product-card-size">' + origSize + '</span>' +
        '<span class="product-card-size">→ ' + resultSize + '</span>' +
        downloadBtn +
      '</div>';

    card.querySelector('.product-card-remove').addEventListener('click', function(e) {
      e.stopPropagation();
      URL.revokeObjectURL(item.url);
      if (item.resultUrl) URL.revokeObjectURL(item.resultUrl);
      files.splice(i, 1);
      renderGrid();
      if (files.length === 0) {
        workspace.style.display = 'none';
        dropzone.style.display = '';
        if (beforeAfter) beforeAfter.classList.remove('hidden');
      }
    });

    productGrid.appendChild(card);
  });

  var done = files.filter(function(f) { return f.resultBlob; });
  downloadAllBtn.style.display = done.length > 1 ? 'inline-block' : 'none';
}

addMoreBtn.addEventListener('click', function() { fileInput.click(); });

processBtn.addEventListener('click', async function() {
  if (!files.length || processing) return;
  processing = true;
  processBtn.disabled = true;
  progBar.style.display = 'block';
  renderGrid();

  // Load model once
  if (!model) {
    status.textContent = 'Loading AI model (first time may take a moment)...';
    try {
      var mod = await import('https://cdn.jsdelivr.net/npm/@imgly/background-removal@1.7.0/+esm');
      model = mod;
    } catch (err) {
      status.textContent = 'Error loading AI model: ' + err.message;
      processing = false;
      processBtn.disabled = false;
      return;
    }
  }

  for (var i = 0; i < files.length; i++) {
    if (files[i].resultBlob) {
      progFill.style.width = (((i + 1) / files.length) * 100) + '%';
      continue;
    }
    status.textContent = 'Processing ' + (i+1) + '/' + files.length + ': ' + files[i].name;
    progFill.style.width = ((i / files.length) * 100) + '%';
    renderGrid();
    try {
      var blob = await model.removeBackground(files[i].url);
      // Composite onto selected background
      var img = await createImageBitmap(blob);
      var canvas = document.createElement('canvas');
      canvas.width = img.width;
      canvas.height = img.height;
      var ctx = canvas.getContext('2d');

      // Draw background color
      if (selectedBg !== 'transparent') {
        ctx.fillStyle = selectedBg;
        ctx.fillRect(0, 0, canvas.width, canvas.height);
      }

      // Draw the product image on top
      ctx.drawImage(img, 0, 0);

      var compositeBlob = await new Promise(function(resolve) {
        canvas.toBlob(function(b) { resolve(b); }, 'image/png');
      });

      files[i].resultBlob = compositeBlob;
      files[i].resultUrl = URL.createObjectURL(compositeBlob);
    } catch (err) {
      files[i].error = true;
      status.textContent = 'Error on ' + files[i].name + ': ' + (err && err.message ? err.message : err);
    }
  }

  progFill.style.width = '100%';
  processing = false;
  processBtn.disabled = false;
  var doneCount = files.filter(function(f) { return f.resultBlob; }).length;
  status.textContent = 'Done! ' + doneCount + ' / ' + files.length + ' processed.';
  setTimeout(function() { progBar.style.display = 'none'; status.textContent = ''; }, 4000);
  renderGrid();
});

downloadAllBtn.addEventListener('click', async function() {
  var done = files.filter(function(f) { return f.resultBlob; });
  if (!done.length) return;
  status.textContent = 'Creating ZIP...';
  try {
    var resp = await fetch('https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js');
    var code = await resp.text();
    eval(code);
    var zip = new JSZip();
    done.forEach(function(item) {
      var outName = (item.name || 'product').replace(/\.[^.]+$/, '') + '-white-bg.png';
      zip.file(outName, item.resultBlob);
    });
    var blob = await zip.generateAsync({ type: 'blob' });
    var a = document.createElement('a');
    a.download = 'product-white-background-images.zip';
    a.href = URL.createObjectURL(blob);
    a.click();
    URL.revokeObjectURL(a.href);
    status.textContent = 'ZIP downloaded!';
    setTimeout(function() { status.textContent = ''; }, 2000);
  } catch (err) {
    // Fallback with script tag loading
    var script = document.createElement('script');
    script.src = 'https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js';
    script.onload = async function() {
      var zip = new JSZip();
      done.forEach(function(item) {
        var outName = (item.name || 'product').replace(/\.[^.]+$/, '') + '-white-bg.png';
        zip.file(outName, item.resultBlob);
      });
      var blob = await zip.generateAsync({ type: 'blob' });
      var a = document.createElement('a');
      a.download = 'product-white-background-images.zip';
      a.href = URL.createObjectURL(blob);
      a.click();
      URL.revokeObjectURL(a.href);
      status.textContent = 'ZIP downloaded!';
      setTimeout(function() { status.textContent = ''; }, 2000);
    };
    document.head.appendChild(script);
  }
});

clearBtn.addEventListener('click', function() {
  files.forEach(function(f) { URL.revokeObjectURL(f.url); if (f.resultUrl) URL.revokeObjectURL(f.resultUrl); });
  files = [];
  productGrid.innerHTML = '';
  workspace.style.display = 'none';
  dropzone.style.display = '';
  progBar.style.display = 'none';
  status.textContent = '';
  if (beforeAfter) beforeAfter.classList.remove('hidden');
  downloadAllBtn.style.display = 'none';
});

// Sample image button
(function() {
  var sampleBtn = document.getElementById('sampleBtn');
  if (sampleBtn) {
    sampleBtn.addEventListener('click', async function(e) {
      e.stopPropagation();
      e.preventDefault();
      sampleBtn.textContent = '⏳ Loading...';
      try {
        var resp = await fetch('https://images.unsplash.com/photo-1542291026-7eec264c27ff?w=800&q=80');
        var blob = await resp.blob();
        var file = new File([blob], 'product-sample.jpg', { type: 'image/jpeg' });
        addFiles([file]);
        sampleBtn.textContent = '🖼️ Try with sample product photos';
      } catch (err) {
        sampleBtn.textContent = '🖼️ Try with sample product photos';
      }
    });
  }
})();

