  genBatchBtn.addEventListener('click', async function() {
    const rows = readBatchRows();
    if (!rows.length) { alert('Silakan masukkan setidaknya satu URL atau teks dalam baris batch.'); return; }
    genBatchBtn.disabled = true;
    genBatchBtn.textContent = '⏳ Menghasilkan ' + rows.length + ' kode QR...';
    batchPreview.innerHTML = '';
    const size = 256;
    const zip = new JSZip();
    const usedNames = {};
    try {
      for (let i = 0; i < rows.length; i++) {
        const payload = rows[i];
        const qr = makeQR(payload);
        const tmpCanvas = document.createElement('canvas');
        drawQRToCanvas(qr, tmpCanvas, size);
        const blob = await new Promise(function(res) { tmpCanvas.toBlob(res); });
        let name = payload.replace(/^https?:\/\//, '').replace(/[\/?&=:#%]/g, '_').slice(0, 40) || ('qr-' + (i + 1));
        if (usedNames[name]) {
          let suffix = 2;
          while (usedNames[name + '-' + suffix]) suffix++;
          name = name + '-' + suffix;
        }
        usedNames[name] = true;
        zip.file(name + '.png', blob);
        const wrap = document.createElement('div');
        wrap.innerHTML = '<img src="' + tmpCanvas.toDataURL() + '"><div style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:2px;">' + name + '</div>';
        batchPreview.appendChild(wrap);
      }
      genBatchBtn.textContent = '⏳ Membuat ZIP...';
      const zipBlob = await zip.generateAsync({ type: 'blob' });
      const a = document.createElement('a');
      a.download = 'qr-batch-' + Date.now() + '.zip';
      a.href = URL.createObjectURL(zipBlob);
      a.click();
      setTimeout(function() { URL.revokeObjectURL(a.href); }, 1000);
      genBatchBtn.textContent = '✅ Selesai! ' + rows.length + ' kode dihasilkan.';
      setTimeout(function() { genBatchBtn.textContent = '✨ Hasilkan Batch (beberapa URL → ZIP)'; genBatchBtn.disabled = false; }, 3000);
    } catch (err) {
      genBatchBtn.textContent = '❌ Kesalahan: ' + err.message;
      genBatchBtn.disabled = false;
      console.error(err);
    }
  });
})();

