function renderCanvas() {
  const bgColor = document.getElementById('bgColorPicker').value;
  const text = document.getElementById('textInput').value;
  const fontSize = parseInt(document.getElementById('fontSizeSlider').value);
  const textColor = document.getElementById('textColorPicker').value;
  const textAlign = document.getElementById('textAlignSelect').value;
  const hasShadow = document.getElementById('shadowToggle').checked;
  const hasOutline = document.getElementById('outlineToggle').checked;
  const logoScaler = parseInt(document.getElementById('logoScaler').value);

  ctx.clearRect(0, 0, canvasW, canvasH);

  // Draw background
  if (bgImage) {
    ctx.drawImage(bgImage, 0, 0, canvasW, canvasH);
  } else {
    ctx.fillStyle = bgColor;
    ctx.fillRect(0, 0, canvasW, canvasH);
  }

  // Draw logo/overlay
  if (logoImage) {
    const scale = logoScaler / 100;
    const lw = logoImage.width * scale;
    const lh = logoImage.height * scale;
    const lx = (canvasW - lw) / 2;
    let ly = (canvasH - lh) / 2 + logoYOffset;
    ctx.drawImage(logoImage, lx, ly, lw, lh);
  }

  // Draw text
  if (text) {
    let alignX = canvasW / 2;
    let textX = canvasW / 2;
    if (textAlign === 'left') {
      textX = canvasW * 0.08;
      alignX = canvasW * 0.08;
    } else if (textAlign === 'right') {
      textX = canvasW * 0.92;
      alignX = canvasW * 0.92;
    } else {
      textX = canvasW / 2;
      alignX = canvasW / 2;
    }
    let textY = canvasH / 2 + textYOffset;

    ctx.textAlign = textAlign;
    ctx.textBaseline = 'middle';

    if (hasOutline) {
      ctx.strokeStyle = '#000000';
      ctx.lineWidth = Math.max(2, fontSize * 0.06);
      ctx.lineJoin = 'round';
      ctx.font = 'bold ' + fontSize + 'px Inter, sans-serif';
      ctx.strokeText(text, textX, textY);
    }

    if (hasShadow) {
      ctx.shadowColor = 'rgba(0,0,0,0.7)';
      ctx.shadowBlur = fontSize * 0.25;
      ctx.shadowOffsetX = Math.max(2, fontSize * 0.04);
      ctx.shadowOffsetY = Math.max(2, fontSize * 0.04);
    }

    ctx.fillStyle = textColor;
    ctx.font = 'bold ' + fontSize + 'px Inter, sans-serif';
    ctx.fillText(text, textX, textY);

    ctx.shadowColor = 'transparent';
    ctx.shadowBlur = 0;
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 0;
  }
}

// Drag-to-position for text (via mouse events on drag overlay)
const dragOverlay = document.getElementById('dragOverlay');
let dragging = false;
let dragMode = 'none';
let dragStartMouseY = 0;
let dragStartTextY = 0;
let dragStartLogoY = 0;

dragOverlay.addEventListener('mousedown', function(e) {
  const rect = dragOverlay.getBoundingClientRect();
  const mx = e.clientX - rect.left;
  const my = e.clientY - rect.top;
  const canvasRect = canvas.getBoundingClientRect();

  // Check if clicking near logo area
  if (logoImage) {
    const scale = parseInt(document.getElementById('logoScaler').value) / 100;
    const lw = logoImage.width * scale;
    const lh = logoImage.height * scale;
    const lx = (canvasW - lw) / 2;
    const ly = (canvasH - lh) / 2 + logoYOffset;
    // Map mouse to canvas coordinates
    const cmx = (mx / rect.width) * canvasW;
    const cmy = (my / rect.height) * canvasH;
    if (cmx >= lx && cmx <= lx + lw && cmy >= ly && cmy <= ly + lh) {
      dragMode = 'logo';
      document.body.style.cursor = 'grabbing';
      return;
    }
  }

  // Default: drag text
  dragMode = 'text';
  document.body.style.cursor = 'grabbing';
});

document.addEventListener('mousemove', function(e) {
  if (dragMode === 'none') return;
  const rect = dragOverlay.getBoundingClientRect();
  const dy = ((e.clientY - rect.top) / rect.height) * canvasH - ((e.clientY - rect.top) / rect.height) * canvasH + (e.movementY / rect.height) * canvasH;

  if (dragMode === 'text') {
    textYOffset = Math.max(-canvasH, Math.min(canvasH, textYOffset + (e.movementY / rect.height) * canvasH));
    document.getElementById('textYSlider').value = Math.round(textYOffset);
    document.getElementById('textYVal').textContent = Math.round(textYOffset);
    renderCanvas();
  } else if (dragMode === 'logo') {
    logoYOffset = Math.max(-canvasH, Math.min(canvasH, logoYOffset + (e.movementY / rect.height) * canvasH));
    document.getElementById('logoYSlider').value = Math.round(logoYOffset);
    document.getElementById('logoYVal').textContent = Math.round(logoYOffset);
    renderCanvas();
  }
});

document.addEventListener('mouseup', function() {
  dragMode = 'none';
  document.body.style.cursor = '';
});

