    });

    // ===== Parse SVG dimensions =====
    function getSvgDimensions(svgString) {
      const parser = new DOMParser();
      const doc = parser.parseFromString(svgString, 'image/svg+xml');
      const svg = doc.querySelector('svg');
      if (!svg) return null;

      let w = parseFloat(svg.getAttribute('width')) || 0;
      let h = parseFloat(svg.getAttribute('height')) || 0;

      // Try viewBox
      const viewBox = svg.getAttribute('viewBox');
      if ((!w || !h) && viewBox) {
        const parts = viewBox.split(/[\s,]+/).map(Number);
        if (parts.length === 4) { w = w || parts[2]; h = h || parts[3]; }
      }
      // Default if still 0
      w = w || 300; h = h || 150;
      return { w, h };
    }

    // ===== Render =====
    function parseAndRender(svgString) {
      const dims = getSvgDimensions(svgString);
      if (!dims) { ImageUtils.showToast('Invalid SVG code', 'error'); return; }
      svgSize = dims;
      document.getElementById('svgSize').textContent = dims.w + ' x ' + dims.h;

      const scale = parseInt(scaleFactor.value);
      canvas.width = dims.w * scale;
      canvas.height = dims.h * scale;

      const img = new Image();
      img.onload = () => {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        document.getElementById('outSize').textContent = canvas.width + ' x ' + canvas.height;
      };
      img.onerror = () => { ImageUtils.showToast('Failed to render SVG', 'error'); };
      // Use data URL for SVG
      const dataUrl = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svgString);
      img.src = dataUrl;
    }

    // ===== Scale Factor Change =====
    scaleFactor.addEventListener('change', () => {
      if (svgSource) parseAndRender(svgSource);
    });

    // ===== Reset =====
    document.getElementById('resetBtn').addEventListener('click', () => {
      svgSource = '';
      svgSize = { w: 0, h: 0 };
      workspace.style.display = 'none';
      dropzone.style.display = '';
      fileInput.value = '';
      svgCodeArea.value = '';
      document.getElementById('svgSize').textContent = '-';
      document.getElementById('outSize').textContent = '-';
    });

    // ===== Download =====
    document.getElementById('downloadBtn').addEventListener('click', () => {
      const mime = outputFormat.value;
      const ext = mime === 'image/jpeg' ? 'jpg' : mime === 'image/webp' ? 'webp' : 'png';
      // Re-render at current scale to ensure freshness
      if (svgSource) {
        parseAndRender(svgSource);
        // Small delay to let canvas render
        setTimeout(() => {
          ImageUtils.download(canvas, 'converted.' + ext, mime);
          ImageUtils.showToast('Image downloaded!');
        }, 100);
      }
    });

  // Next Step
  (function() {
    var dlBtn = document.getElementById('downloadBtn') || document.querySelector('[id*="download"], [id*="Download"]');
    if (dlBtn) {
      dlBtn.addEventListener('click', function() { SmartImgNextStep.show(); });
    }
  })();

// ===== State =====
    let originalImg = null;
    let textX = 0.5;  // proportional position (0-1)
    let textY = 0.5;
    let isDragging = false;

    // ===== DOM =====
    const dropzone = document.getElementById('dropzone');
    const fileInput = document.getElementById('fileInput');
    const workspace = document.getElementById('workspace');
    const previewCanvas = document.getElementById('previewCanvas');
    const ctx = previewCanvas.getContext('2d');
    const canvasWrapper = document.getElementById('canvasWrapper');
    const textInput = document.getElementById('textInput');
    const fontFamily = document.getElementById('fontFamily');
    const fontSize = document.getElementById('fontSize');
    const sizeValue = document.getElementById('sizeValue');
    const fontWeight = document.getElementById('fontWeight');
    const textColor = document.getElementById('textColor');
    const outlineColor = document.getElementById('outlineColor');
    const outlineWidth = document.getElementById('outlineWidth');
    const outlineValue = document.getElementById('outlineValue');
    const shadowBlur = document.getElementById('shadowBlur');
    const shadowValue = document.getElementById('shadowValue');
    const opacity = document.getElementById('opacity');
    const opacityValue = document.getElementById('opacityValue');
    const rotation = document.getElementById('rotation');
    const rotationValue = document.getElementById('rotationValue');
    const outputFormat = document.getElementById('outputFormat');
    const downloadBtn = document.getElementById('downloadBtn');
    const resetBtn = document.getElementById('resetBtn');
    const status = document.getElementById('status');

    // ===== Upload =====
    setupDropzone({ dropzoneId: 'dropzone', inputId: 'fileInput', onFile: handleFile });

    async function handleFile(file) {
      if (!file.type.startsWith('image/')) return;
      originalImg = await ImageUtils.load(file);
      textX = 0.5; textY = 0.5;
      dropzone.classList.add('hidden');
      workspace.style.display = '';
      renderPreview();
    }

    // ===== Controls =====
    const liveControls = [textInput, fontFamily, fontWeight, textColor, outlineColor];
    liveControls.forEach(el => el.addEventListener('input', () => renderPreview()));

    const sliderControls = [
      [fontSize, sizeValue], [outlineWidth, outlineValue],
      [shadowBlur, shadowValue], [opacity, opacityValue], [rotation, rotationValue]
    ];
    sliderControls.forEach(([slider, display]) => {
      slider.addEventListener('input', () => { display.textContent = slider.value; renderPreview(); });
    });

    // ===== Quick Position =====
    document.querySelectorAll('.pos-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        document.querySelectorAll('.pos-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        textX = parseFloat(btn.dataset.x);
        textY = parseFloat(btn.dataset.y);
        renderPreview();
      });
    });

    // ===== Drag on Canvas =====
    previewCanvas.addEventListener('mousedown', startDrag);
    previewCanvas.addEventListener('touchstart', startDrag, { passive: false });

    function startDrag(e) {
      e.preventDefault();
      isDragging = true;
      moveDrag(e);
      document.addEventListener('mousemove', moveDrag);
      document.addEventListener('mouseup', stopDrag);
      document.addEventListener('touchmove', moveDrag, { passive: false });
      document.addEventListener('touchend', stopDrag);
    }

    function moveDrag(e) {
      if (!isDragging || !originalImg) return;
      e.preventDefault();
      const rect = previewCanvas.getBoundingClientRect();
      const clientX = e.touches ? e.touches[0].clientX : e.clientX;
      const clientY = e.touches ? e.touches[0].clientY : e.clientY;
      textX = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
      textY = Math.max(0, Math.min(1, (clientY - rect.top) / rect.height));
      document.querySelectorAll('.pos-btn').forEach(b => b.classList.remove('active'));
      renderPreview();
    }

    function stopDrag() {
      isDragging = false;
      document.removeEventListener('mousemove', moveDrag);
      document.removeEventListener('mouseup', stopDrag);
      document.removeEventListener('touchmove', moveDrag);
      document.removeEventListener('touchend', stopDrag);
    }

    // ===== Preview Render =====
    function renderPreview() {
      if (!originalImg) return;
      const w = originalImg.naturalWidth;
      const h = originalImg.naturalHeight;

      previewCanvas.width = w;
      previewCanvas.height = h;
      ctx.drawImage(originalImg, 0, 0, w, h);

      const text = textInput.value;
      if (!text) return;

      const fSize = parseInt(fontSize.value);
      const fWeight = fontWeight.value;
      const fFamily = fontFamily.value;
      const tColor = textColor.value;
      const oColor = outlineColor.value;
      const oWidth = parseInt(outlineWidth.value);
      const sBlur = parseInt(shadowBlur.value);
      const alpha = parseInt(opacity.value) / 100;
      const rot = parseInt(rotation.value) * Math.PI / 180;

      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.font = `${fWeight} ${fSize}px "${fFamily}"`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';

      const px = textX * w;
      const py = textY * h;

      ctx.translate(px, py);
      ctx.rotate(rot);

      // Shadow
      if (sBlur > 0) {
        ctx.shadowColor = 'rgba(0,0,0,0.6)';
        ctx.shadowBlur = sBlur;
        ctx.shadowOffsetX = Math.round(sBlur / 4);
        ctx.shadowOffsetY = Math.round(sBlur / 4);
      }

      // Draw multiline text
      const lines = text.split('\n');
      const lineHeight = fSize * 1.3;
      const totalHeight = lineHeight * lines.length;
      const startY = -(totalHeight / 2) + lineHeight / 2;

      lines.forEach((line, i) => {
        const ly = startY + i * lineHeight;

        // Outline
        if (oWidth > 0) {
          ctx.strokeStyle = oColor;
          ctx.lineWidth = oWidth * 2;
          ctx.lineJoin = 'round';
          ctx.miterLimit = 2;
          ctx.strokeText(line, 0, ly);
        }

        // Fill
        ctx.fillStyle = tColor;
        ctx.fillText(line, 0, ly);
      });

      ctx.restore();
    }

    // ===== Download =====
    downloadBtn.addEventListener('click', async () => {
      if (!originalImg) return;
      downloadBtn.disabled = true;
      downloadBtn.textContent = '🔄 Processing...';
      status.textContent = '';
      try {
        const format = outputFormat.value;
        const quality = format === 'image/png' ? undefined : 0.92;
        const blob = await ImageUtils.canvasToBlob(previewCanvas, format, quality);
        const ext = format === 'image/png' ? 'png' : format === 'image/jpeg' ? 'jpg' : 'webp';
        ImageUtils.download(blob, `text-on-image.${ext}`);
        status.textContent = '✅ Image downloaded!';
      } catch (e) {
        status.textContent = '❌ Error: ' + e.message;
      }
      downloadBtn.disabled = false;
      downloadBtn.textContent = '💾 Download';
    });

    // ===== Reset =====
    resetBtn.addEventListener('click', () => {
      originalImg = null;
      workspace.style.display = 'none';
      dropzone.classList.remove('hidden');
      fileInput.value = '';
      textInput.value = 'Hello World';
      status.textContent = '';
    });

  // Sample image & Next Step
  (function() {
    var _handleFile = typeof handleFile === 'function' ? handleFile : null;
    if (_handleFile) {
      window.initSampleButton('https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80', _handleFile);
    }
    // Show next-step on download click
    var dlBtn = document.getElementById('downloadBtn') || document.querySelector('.btn-primary[onclick*="download"], .btn-secondary[onclick*="download"]');
    if (dlBtn) {
      dlBtn.addEventListener('click', function() { SmartImgNextStep.show(); });
    }
  })();

let files = [];
let wmImage = null;
let mode = 'text';

const fileInput = document.getElementById('fileInput');
const dropzone = document.getElementById('dropzone');
const workspace = document.getElementById('workspace');
const previewList = document.getElementById('previewList');
const applyBtn = document.getElementById('applyBtn');
const downloadAllBtn = document.getElementById('downloadAllBtn');
const addMoreBtn = document.getElementById('addMoreBtn');
const clearBtn = document.getElementById('clearBtn');
const progBar = document.getElementById('progBar');
const progFill = document.getElementById('progFill');
const status = document.getElementById('status');
const textModeBtn = document.getElementById('textModeBtn');
const imgModeBtn = document.getElementById('imgModeBtn');
const textControls = document.getElementById('textControls');
const imgControls = document.getElementById('imgControls');
const wmText = document.getElementById('wmText');
const wmColor = document.getElementById('wmColor');
const wmSize = document.getElementById('wmSize');
const wmOp = document.getElementById('wmOp');
const wmImgInput = document.getElementById('wmImgInput');
const wmImgOp = document.getElementById('wmImgOp');
const wmPos = document.getElementById('wmPos');
const beforeAfter = document.getElementById('beforeAfterPreview');

textModeBtn.addEventListener('click', function() { mode = 'text'; textControls.classList.remove('hidden'); imgControls.classList.add('hidden'); });
imgModeBtn.addEventListener('click', function() { mode = 'image'; textControls.classList.add('hidden'); imgControls.classList.remove('hidden'); });

wmImgInput.addEventListener('change', async function() {
  if (wmImgInput.files[0]) {
    const img = new Image();
    await new Promise(function(res, rej) { img.onload = res; img.onerror = rej; img.src = URL.createObjectURL(wmImgInput.files[0]); });
    wmImage = img;
  }
});

fileInput.addEventListener('change', function() {
  const arr = Array.from(fileInput.files).filter(f => f.type && f.type.startsWith('image/'));
  if (arr.length) addFiles(arr);
  fileInput.value = '';
});
dropzone.addEventListener('dragover', function(e) { e.preventDefault(); dropzone.classList.add('drag'); });
dropzone.addEventListener('dragleave', function() { dropzone.classList.remove('drag'); });
dropzone.addEventListener('drop', function(e) {
  e.preventDefault();
  dropzone.classList.remove('drag');
  const arr = Array.from(e.dataTransfer.files).filter(f => f.type && f.type.startsWith('image/'));
  if (arr.length) addFiles(arr);
});

function addFiles(arr) {
  files = files.concat(arr.map(f => ({ name: f.name, file: f, url: URL.createObjectURL(f), img: null, resultUrl: null, resultBlob: null })));
  dropzone.style.display = 'none';
  workspace.style.display = 'block';
  if (beforeAfter) beforeAfter.classList.add('hidden');
  preloadImages();
}

function preloadImages() {
  let pending = 0;
  files.forEach(function(item) {
    if (item.img) return;
    pending++;
    const img = new Image();
    img.onload = function() { item.img = img; if (--pending === 0) renderList(); };
    img.src = item.url;
  });
  if (pending === 0) renderList();
}

function formatSize(bytes) {
  if (bytes < 1024) return bytes + ' B';
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
  return (bytes / (1024 * 1024)).toFixed(2) + ' MB';
}

function renderList() {
  previewList.innerHTML = '';
  files.forEach(function(item, i) {
    const div = document.createElement('div');
    div.className = 'prev-item';
    const ext = item.file.type === 'image/png' ? '.png' : '.jpg';
    const outName = item.name.replace(/\.[^.]+$/, '') + '-watermarked' + ext;
    let info = '<p>Original: ' + formatSize(item.file.size) + '</p>';
    let dl = '';
    if (item.resultBlob) {
      info += '<p><span class="badge badge-done">✅ Done</span> Output: ' + formatSize(item.resultBlob.size) + '</p>';
      dl = '<a href="' + item.resultUrl + '" download="' + outName + '" class="btn btn-secondary" style="padding:4px 10px;font-size:0.8rem;align-self:center">Unduh</a>';
    } else {
      info += '<p>⏳ Waiting...</p>';
    }
    div.innerHTML = '<img class="thumb" src="' + item.url + '"><div class="info"><p><strong>' + item.name + '</strong></p>' + info + '</div>' + dl + '<button title="Remove" style="align-self:flex-start">✕</button>';
    div.querySelector('button').addEventListener('click', function(e) {
      e.stopPropagation();
      URL.revokeObjectURL(item.url);
      if (item.resultUrl) URL.revokeObjectURL(item.resultUrl);
      files.splice(i, 1);
      renderList();
    });
    previewList.appendChild(div);
  });
  const done = files.filter(function(f) { return f.resultBlob; });
  downloadAllBtn.style.display = done.length > 1 ? 'inline-block' : 'none';
}

addMoreBtn.addEventListener('click', function() { fileInput.click(); });

async function applyWatermarkToImage(img) {
  const canvas = document.createElement('canvas');
  canvas.width = img.naturalWidth;
  canvas.height = img.naturalHeight;
  const ctx = canvas.getContext('2d');
  ctx.drawImage(img, 0, 0);
  const pos = wmPos.value;
  const pad = 20;
  let x = 0, y = 0;
  if (mode === 'text') {
    const size = parseInt(wmSize.value) || 48;
    ctx.font = size + 'px sans-serif';
    ctx.globalAlpha = (parseInt(wmOp.value) || 50) / 100;
    ctx.fillStyle = wmColor.value;
    const metrics = ctx.measureText(wmText.value);
    if (pos === 'bottom-right') { x = canvas.width - metrics.width - pad; y = canvas.height - pad; }
    else if (pos === 'bottom-left') { x = pad; y = canvas.height - pad; }
    else if (pos === 'top-right') { x = canvas.width - metrics.width - pad; y = size + pad; }
    else if (pos === 'top-left') { x = pad; y = size + pad; }
    else if (pos === 'center') { x = (canvas.width - metrics.width) / 2; y = canvas.height / 2; }
    ctx.fillText(wmText.value, x, y);
  } else if (mode === 'image' && wmImage) {
    const op = (parseInt(wmImgOp.value) || 50) / 100;
    const iw = canvas.width * 0.2, ih = iw * (wmImage.naturalHeight / wmImage.naturalWidth);
    ctx.globalAlpha = op;
    if (pos === 'bottom-right') { x = canvas.width - iw - pad; y = canvas.height - ih - pad; }
    else if (pos === 'bottom-left') { x = pad; y = canvas.height - ih - pad; }
    else if (pos === 'top-right') { x = canvas.width - iw - pad; y = pad; }
    else if (pos === 'top-left') { x = pad; y = pad; }
    else if (pos === 'center') { x = (canvas.width - iw) / 2; y = (canvas.height - ih) / 2; }
    ctx.drawImage(wmImage, x, y, iw, ih);
  }
  ctx.globalAlpha = 1;
  return new Promise(function(resolve) {
    canvas.toBlob(function(blob) { resolve(blob); }, item.file.type === 'image/png' ? 'image/png' : 'image/jpeg', 0.92);
  });
}

applyBtn.addEventListener('click', async function() {
  if (!files.length) return;
  if (mode === 'image' && !wmImage) { status.textContent = 'Please select a watermark image first.'; return; }
  applyBtn.disabled = true;
  progBar.style.display = 'block';
  for (let i = 0; i < files.length; i++) {
    if (files[i].resultBlob) { progFill.style.width = (((i + 1) / files.length) * 100) + '%'; continue; }
    status.textContent = 'Watermarking ' + (i+1) + '/' + files.length + ': ' + files[i].name;
    progFill.style.width = ((i / files.length) * 100) + '%';
    try {
      if (!files[i].img) {
        files[i].img = await new Promise(function(res, rej) {
          const im = new Image();
          im.onload = function() { res(im); };
          im.onerror = rej;
          im.src = files[i].url;
        });
      }
      const blob = await applyWatermarkToImage(files[i].img, files[i]);
      files[i].resultBlob = blob;
      files[i].resultUrl = URL.createObjectURL(blob);
    } catch (err) {
      status.textContent = 'Error: ' + err.message;
      console.error(err);
    }
  }
  progFill.style.width = '100%';
  status.textContent = 'Done! ' + files.filter(function(f) { return f.resultBlob; }).length + ' watermarked.';
  setTimeout(function() { progBar.style.display = 'none'; status.textContent = ''; }, 4000);
  applyBtn.disabled = false;
  renderList();
});

downloadAllBtn.addEventListener('click', async function() {
  const zip = new JSZip();
  files.forEach(function(item) {
    if (item.resultBlob) {
      const ext = item.file.type === 'image/png' ? '.png' : '.jpg';
      const outName = item.name.replace(/\.[^.]+$/, '') + '-watermarked' + ext;
      zip.file(outName, item.resultBlob);
    }
  });
  status.textContent = 'Creating ZIP...';
  const blob = await zip.generateAsync({ type: 'blob' });
  const a = document.createElement('a');
  a.download = 'watermarked-images.zip';
  a.href = URL.createObjectURL(blob);
  a.click();
  URL.revokeObjectURL(a.href);
  status.textContent = 'ZIP downloaded!';
  setTimeout(function() { status.textContent = ''; }, 2000);
});

clearBtn.addEventListener('click', function() {
  files.forEach(function(f) { URL.revokeObjectURL(f.url); if (f.resultUrl) URL.revokeObjectURL(f.resultUrl); });
  files = [];
  previewList.innerHTML = '';
  workspace.style.display = 'none';
  dropzone.style.display = '';
  progBar.style.display = 'none';
  status.textContent = '';
  if (beforeAfter) beforeAfter.classList.remove('hidden');
});

